(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("philo-the-decalogue-e", [{"sp": "HDR", "t": "Περὶ τῶν δέκα λογίων"}, {"sp": "N", "t": "Τοὺς βίους τῶν κατὰ Μωυσέα σοφῶν ἀνδρῶν, οὓς ἀρχηγέτας τοῦ ἡμετέρου ἔθνους καὶ νόμους ἀγράφους αἱ ἱεραὶ βίβλοι δηλοῦσιν, ἐν ταῖς προτέραις συντάξεσι μεμηνυκὼς κατὰ τὰ ἀκόλουθα ἑξῆς τῶν ἀναγραφέντων νόμων τὰς ἰδέας ἀκριβώσω μηδ’, εἴ τις ὑποφαίνοιτο τρόπος ἀλληγορίας, τοῦτον παρεὶς ἕνεκα τῆς πρὸς διάνοιαν φιλομαθοῦς ἐπιστήμης, ᾗ πρὸ τῶν ἐμφανῶν ἔθος τὰ ἀφανῆ ζητεῖν.", "st": "1"}, {"sp": "N", "t": "πρὸς δὲ τοὺς ἀποροῦντας, τί δή ποτε οὐκ ἐν πόλεσιν ἀλλ’ ἐν ἐρήμῳ βαθείᾳ τοὺς νόμους ἐτίθει, λεκτέον πρῶτον μέν, ὅτι αἱ πολλαὶ τῶν πόλεων ἀμυθήτων κακῶν εἰσι μεσταί, καὶ τῶν πρὸς τὸ θεῖον ἀνοσιουργημάτων καὶ τῶν πρὸς ἀλλήλους ἀδικημάτων.", "st": "2"}, {"sp": "N", "t": "οὐδὲν γάρ ἐστιν ὃ μὴ κεκιβδήλευται, τὰ γνήσια τῶν νόθων παρευημερούντων καὶ τἀληθῆ τῶν εἰκότων, ἃ φύσει μὲν κατέψευσται, πιθανὰς δ’ ὑποβάλλει φαντασίας πρὸς ἀπάτην.", "st": "3"}, {"sp": "N", "t": "ἐν πόλεσιν οὖν καὶ ὁ πάντων ἐπιβουλότατος φύεται τῦφος, ὅν τινες τεθήπασι καὶ προσκυνοῦσι τὰς κενὰς δόξας σεμνοποιοῦντες διὰ χρυσῶν στεφάνων καὶ ἁλουργίδων καὶ πλήθους θεραπόντων καὶ ὀχημάτων, ἐφ’ ὧν οἱ λεγόμενοι μακάριοι καὶ εὐδαίμονες μετέωροι φέρονται, τοτὲ μὲν ὀρεῖς ἢ ἵππους καταζευγνύντες τοτὲ δὲ καὶ ἀνθρώπους, οἳ τὰ φορεῖα κατὰ τῶν αὐχένων ἀχθοφοροῦσι τὴν ψυχὴν", "st": "4"}, {"sp": "N", "t": "πρὸ τοῦ σώματος δι’ ὑπερβολὴν ὕβρεως πιεζόμενοι. τῦφος καὶ πολλῶν ἄλλων κακῶν δημιουργός ἐστιν, ἀλαζονείας, ὑπεροψίας, ἀνισότητος· αἱ δ’ εἰσὶν ἀρχαὶ ξενικῶν καὶ ἐμφυλίων πολέμων οὐδὲν μέρος, οὐ κοινόν, οὐκ ἴδιον, οὐ κατὰ γῆν, οὐ κατὰ θάλατταν, ἡσυχάζειν ἐῶσαι. τί δὲ δεῖ τῶν πρὸς ἀλλήλους ἁμαρτημάτων μεμνῆσθαι;", "st": "5"}, {"sp": "N", "t": "τύφῳ γὰρ καὶ τὰ θεῖα ἐξωλιγώρηται, καίτοι νομιζόμενα τῆς ἀνωτάτω τυγχάνειν τιμῆς· τιμὴ δὲ τίς ἂν γένοιτο, μὴ προσούσης ἀληθείας, ἣ καὶ ὄνομα καὶ ἔργον ἔχει τίμιον, ἐπεὶ καὶ τὸ ψεῦδος ἔμπαλιν ἄτιμον φύσει;", "st": "6"}, {"sp": "N", "t": "ἡ δ’ ὀλιγωρία τῶν θείων ἐμφανὴς τοῖς ὀξυδερκέστερον ὁρῶσι· μυρίας γὰρ ὅσας διὰ γραφικῆς καὶ πλαστικῆς μορφώσαντες ἰδέας ἱερὰ καὶ νεὼς αὐταῖς προσπεριεβάλοντο καὶ βωμοὺς κατασκευάσαντες ἀγάλμασι καὶ ξοάνοις καὶ τοιουτοτρόποις ἀφιδρύμασι τιμὰς ἰσολυμπίους καὶ ἰσοθέους ἀπένειμαν, ἅπασιν ἀψύχοις.", "st": "7"}, {"sp": "N", "t": "οὓς εὐθυβόλως αἱ ἱεραὶ γραφαὶ τοῖς ἐκ πόρνης γεγονόσιν ἀπεικάζουσιν· ὡς γὰρ οὗτοι πάντας, ὅσους ἐραστὰς ἔσχεν ἡ μήτηρ, ἐπιγράφονται πατέρας ἑνὸς ἀγνοίᾳ τοῦ φύσει, οὕτω καὶ οἱ κατὰ πόλεις οὐκ εἰδότες τὸν ὄντα ὄντως ἀληθῆ θεὸν μυρία πλήθη ψευδωνύμων ἐκτεθειώκασιν.", "st": "8"}, {"sp": "N", "t": "εἶτ’ ἄλλων παρ’ ἄλλοις τιμωμένων, ἡ περὶ τοῦ ἀρίστου κρατήσασα διχόνοια καὶ τὰς πρὸς τὰ ἄλλα πάντα διαφορὰς ἐγέννησεν.", "st": "9"}, {"sp": "N", "t": "εἰς ἃ πρῶτον ἀπιδὼν ἔξω πόλεων ἐβουλήθη νομοθετεῖν. ἐνενόει δὲ κἀκεῖνο δεύτερον, ὅτι τοῦ μέλλοντος ἱεροὺς νόμους παραδέχεσθαι τὴν ψυχὴν ἀναγκαῖόν ἐστιν ἀπορρύψασθαι καὶ ἐκκαθήρασθαι τὰς δυσεκπλύτους κηλῖδας, ἃς μιγάδων καὶ συγκλύδων ὄχλος ἀνθρώπων κατὰ πόλεις προσετρίψατο.", "st": "10"}, {"sp": "N", "t": "τοῦτο δὲ ἀμήχανον ἑτέρως ἢ διοικισθέντι συμβῆναι, καὶ οὐκ εὐθὺς ἀλλὰ μακρῷ χρόνῳ ὕστερον, ἕως ἂν οἱ τῶν ἀρχαίων παρανομημάτων ἐνσφραγισθέντες τύποι κατὰ μικρὸν ἀμαυρούμενοι καὶ ἀπορρέοντες ἀφανισθῶσι.", "st": "11"}, {"sp": "N", "t": "τοῦτον τὸν τρόπον καὶ οἱ τὴν ἰατρικὴν ἀγαθοὶ σῴζουσι τοὺς κάμνοντας· οὐ γὰρ πρότερον σιτία καὶ ποτὰ παρέχειν ἀξιοῦσι, πρὶν ἢ τὰ τῶν νόσων αἴτια ὑπεξελέσθαι· μενόντων γὰρ ἀνωφελεῖς αἱ τροφαί, ἀλλὰ καὶ ἐπιζήμιοι, ὗλαι γινόμεναι τοῦ πάθους.", "st": "12"}, {"sp": "N", "t": "εἰκότως οὖν ἐκ τῶν κατὰ πόλεις βλαβερωτάτων συνηθειῶν εἰς ἐρήμην ἀπαγαγών, ἵνα κενώσῃ τὰς ψυχὰς ἀδικημάτων, ἤρξατο προσφέρειν ταῖς διανοίαις τροφάς· αὗται δὲ τίνες ἂν εἶεν ὅτι μὴ νόμοι καὶ λόγοι θεῖοι;", "st": "13"}, {"sp": "N", "t": "τρίτη δέ ἐστιν αἰτία ἥδε· καθάπερ οἱ στελλόμενοι μακρὸν πλοῦν, οὐχ ὅταν ἐπιβάντες τῆς νεὼς ἀπὸ λιμένος ἐξαναχθῶσιν, ἄρχονται κατασκευάζειν ἱστία καὶ πηδάλια καὶ οἴακας, ἀλλ’ ἔτι μένοντες ἐπὶ γῆς ἕκαστα τῶν συντεινόντων πρὸς πλοῦν εὐτρεπίζονται, τὸν αὐτὸν τρόπον ἠξίωσεν οὐ λαβόντας κληρουχίας καὶ τὰς πόλεις οἰκήσαντας τότε ζητεῖν νόμους, οἷς πολιτεύσονται, ἀλλ’ ἑτοιμασαμένους τοὺς τῆς πολιτείας κανόνας καὶ ἐνασκηθέντας οἷς ἔμελλον οἱ δῆμοι κυβερνᾶσθαι σωτηρίως τηνικαῦτα εἰσοικίζεσθαι, χρησομένους εὐθὺς ταῖς τῶν δικαίων παρασκευαῖς ἐν ὁμονοίᾳ καὶ κοινωνίᾳ καὶ διανομῇ τῶν ἐπιβαλλόντων ἑκάστοις.", "st": "14"}, {"sp": "N", "t": "φασὶ δέ τινες καὶ τετάρτην αἰτίαν οὐκ ἀπῳδὸν ἀλλ’ ἐγγυτάτω τῆς ἀληθείας· ἐπειδὴ γὰρ ἔδει πίστιν ἐγγενέσθαι ταῖς διανοίαις περὶ τοῦ μὴ εὑρήματα ἀνθρώπου τοὺς νόμους ἀλλὰ θεοῦ χρησμοὺς σαφεστάτους εἶναι, πορρωτάτω τῶν πόλεων ἀπήγαγε τὸ ἔθνος εἰς ἐρήμην βαθεῖαν καὶ ἄγονον οὐ μόνον ἡμέρων καρπῶν ἀλλὰ καὶ ποτίμου ὕδατος, ἵν’,", "st": "15"}, {"sp": "N", "t": "ἐὰν ἐν σπάνει γενόμενοι τῶν ἀναγκαίων καὶ δίψει καὶ λιμῷ διαφθαρῆναι προσδοκήσαντες ἐξαπιναίως ἀφθονίαν τῶν ἐπιτηδείων ἀπαυτοματισθέντων ἀνευρίσκωσιν, οὐρανοῦ μὲν ὕοντος τροφὰς τὸ καλούμενον μάννα, προσόψημα δὲ τροφῶν ἀπ’ ἀέρος ὀρτυγομήτρας φοράν, ὕδατος δὲ πικροῦ γλυκαινομένου πρὸς τὸ πότιμον, πέτρας δὲ ἀκροτόμου πηγὰς ἀνομβρούσης, μηκέτι θαυμάζωσιν, εἰ λόγια θεοῦ συμβέβηκεν εἶναι τοὺς νόμους, ἐναργεστάτην βάσανον εἰληφότες ἐκ τῶν χορηγιῶν, ἃς ἐξ ἀπόρων ἔσχον οὐκ ἐλπίσαντες.", "st": "16"}, {"sp": "N", "t": "ὁ γὰρ πρὸς τὸ ζῆν ἀφθονίαν δοὺς καὶ τὰς πρὸς τὸ εὖ ζῆν ἀφορμὰς ἐδωρεῖτο· πρὸς μὲν οὖν τὸ ζῆν σιτίων ἔδει καὶ ποτῶν, ἅπερ ἀνεύρισκον οὐχ ἑτοιμασάμενοι, πρὸς δὲ τὸ εὖ ζῆν νόμων καὶ διαταγμάτων, οἷς βελτιοῦσθαι τὰς ψυχὰς ἔμελλον.", "st": "17"}, {"sp": "N", "t": "Αἵδ’ εἰσὶν ἐν στοχασμοῖς εἰκόσιν αἰτίαι λεγόμεναι περὶ τοῦ διαπορηθέντος· τὰς γὰρ ἀληθεῖς οἶδεν ὁ θεὸς μόνος. εἰπὼν δ’ ἅπερ ἥρμοττε περὶ τούτων ἑξῆς αὐτοὺς ἀκριβώσω τοὺς νόμους, ἐκεῖνο κατὰ τὸ ἀναγκαῖον προμηνύσας, ὅτι τῶν νόμων οὓς μὲν αὐτὸς ὁ θεὸς οὐ προσχρησάμενος ἄλλῳ δι’ ἑαυτοῦ μόνου θεσπίζειν ἠξίωσεν, οὓς δὲ διὰ προφήτου Μωυσέως, ὃν ἀριστίνδην ἐκ πάντων ὡς ἐπιτηδειότατον ἱεροφάντην ἐπελέξατο.", "st": "18"}, {"sp": "N", "t": "τοὺς μὲν οὖν αὐτοπροσώπως θεσπισθέντας δι’ αὐτοῦ μόνου συμβέβηκε καὶ νόμους εἶναι καὶ νόμων τῶν ἐν μέρει κεφάλαια, τοὺς δὲ διὰ τοῦ προφήτου πάντας ἐπ’ ἐκείνους ἀναφέρεσθαι.", "st": "19"}, {"sp": "N", "t": "λέξω δ’, ὡς ἂν οἷός τε ὦ, περὶ ἑκατέρων καὶ πρότερόν γε τῶν κεφαλαιωδεστέρων· ὧν εὐθέως ἄξιον θαυμάσαι τὸν ἀριθμὸν δεκάδι τῇ παντελείᾳ περατουμένων, ἣ πάσας μὲν ἀριθμῶν διαφορὰς ἀρτίων καὶ περιττῶν καὶ ἀρτιοπερίττων, ἀρτίων μὲν δυοῖν, περιττῶν δὲ τριῶν, ἀρτιοπερίττων δὲ πέντε, πάσας δὲ λόγων τῶν ἐν ἀριθμοῖς πολυπλασίων καὶ ἐπιμερῶν καὶ ὑποεπιμερῶν περιέχει, πάσας δ’ ἀναλογίας,", "st": "20"}, {"sp": "N", "t": "τήν τε ἀριθμητικήν, ἣ τῷ ἰσαρίθμῳ ὑπερέχει καὶ ὑπερέχεται, οἷον ἐπὶ τοῦ ἓν καὶ δύο καὶ τρία, καὶ τὴν γεωμετρικήν, καθ’ ἣν οἷος ὁ λόγος πρὸς τὸν πρῶτον τοῦ δευτέρου, τοιοῦτος καὶ ὁ πρὸς τὸν δεύτερον τοῦ τρίτου, ὡς ἔχει ἐπὶ τοῦ ἓν καὶ δύο καὶ τέσσαρα, ἔν τε διπλασίοις καὶ τριπλασίοις καὶ συνόλως πολυπλασίοις καὶ πάλιν ἐν ἡμιολίοις καὶ ἐπιτρίτοις καὶ τοῖς παραπλησίοις, ἔτι μέντοι καὶ τὴν ἁρμονικήν, καθ’ ἣν ὁ μέσος τῶν ἄκρων τῷ ἴσῳ μορίῳ ὑπερέχει τε καὶ ὑπερέχεται, ὡς ἔχει ἐπὶ τοῦ τρίτου καὶ τετάρτου καὶ ἕκτου.", "st": "21"}, {"sp": "N", "t": "περιέχει δὲ ἡ δεκὰς καὶ τὰς τῶν τριγώνων καὶ τετραγώνων καὶ τῶν ἄλλων πολυγώνων ἐμφαινομένας ἰδιότητας καὶ τὰς τῶν συμφωνιῶν, τήν τε διὰ τεσσάρων ἐν ἐπιτρίτῳ λόγῳ, τῷ τέσσαρα πρὸς τρία, καὶ τὴν διὰ πέντε ἐν ἡμιολίῳ, τῷ τρία πρὸς δύο, καὶ τὴν διὰ πασῶν ἐν διπλασίῳ, τῷ δύο πρὸς ἕν, καὶ τὴν δὶς διὰ πασῶν ἐν τετραπλασίῳ, τῷ ὀκτὼ πρὸς δύο.", "st": "22"}, {"sp": "N", "t": "παρό μοι δοκοῦσι καὶ οἱ πρῶτοι τὰ ὀνόματα τοῖς πράγμασι θέμενοι — σοφοὶ γὰρ ἦσαν — εἰκότως αὐτὴν προσαγορεῦσαι δεκάδα, ὡσανεὶ δεχάδα οὖσαν, παρὰ τὸ δέχεσθαι καὶ κεχωρηκέναι τὰ γένη πάντα τῶν ἀριθμῶν καὶ λόγων τῶν κατ’ ἀριθμὸν", "st": "23"}, {"sp": "N", "t": "καὶ ἀναλογιῶν ἁρμονιῶν τε αὖ καὶ συμφωνιῶν. τὴν μέντοι δεκάδα πρὸς τοῖς εἰρημένοις καὶ διὰ ταῦτα εἰκότως ἄν τις θαυμάσειε περιέχουσαν τήν τε ἀδιάστατον φύσιν καὶ τὴν διαστηματικήν· ἡ μὲν οὖν ἀδιάστατος τάττεται κατὰ σημεῖον μόνον, ἡ δὲ διαστηματικὴ κατὰ τρεῖς ἰδέας γραμμῆς καὶ ἐπιφανείας καὶ στερεοῦ·", "st": "24"}, {"sp": "N", "t": "τὸ μὲν γὰρ δυσὶ σημείοις περατούμενόν ἐστι γραμμή, τὸ δ’ ἐπὶ δύο διαστατὸν ἐπιφάνεια, ῥυείσης ἐπὶ πλάτος γραμμῆς, τὸ δ’ ἐπὶ τρία στερεόν, μήκους καὶ πλάτους βάθος προσλαβόντων, ἐφ’ ὧν ἵσταται ἡ φύσις· πλείους γὰρ τριῶν διαστάσεις οὐκ ἐγέννησεν.", "st": "25"}, {"sp": "N", "t": "ἀρχέτυποι δὲ τούτων ἀριθμοὶ τοῦ μὲν ἀδιαστάτου σημείου τὸ ἕν, τῆς δὲ γραμμῆς τὰ δύο, καὶ ἐπιφανείας μὲν τρία, στερεοῦ δὲ τέσσαρα, ὧν ἡ σύνθεσις ἑνὸς καὶ δυοῖν καὶ τριῶν καὶ τεσσάρων ἀποτελεῖ δεκάδα παραφαίνουσαν τοῖς ὁρατικοῖς καὶ ἕτερα κάλλη·", "st": "26"}, {"sp": "N", "t": "σχεδὸν γὰρ ἡ ἀπειρία τῶν ἀριθμῶν ταύτῃ μετρεῖται, διότι οἱ συστήσαντες αὐτὴν ὅροι τέσσαρές εἰσιν, ἓν καὶ δύο καὶ τρία καὶ τέτταρα, οἱ δ’ ἴσοι ὅροι ἑκατοντάδα γεννῶσιν ἐκ δεκάδων — δέκα γὰρ καὶ εἴκοσι καὶ τριάκοντα καὶ τεσσαράκοντα γίνονται ἑκατόν —, ὁμοίως δὲ καὶ χιλιάδα ἐξ ἑκατοντάδων καὶ μυριάδα ἐκ χιλιάδων, μονὰς δὲ καὶ δεκὰς καὶ ἑκατοντὰς καὶ χιλιὰς τέσσαρες ὅροι οἱ δεκάδα γεννῶντες·", "st": "27"}, {"sp": "N", "t": "ἥτις δίχα τῶν πρόσθεν εἰρημένων καὶ ἑτέρας ἀριθμῶν ἐμφαίνει διαφοράς, τόν τε πρῶτον κόσμον, ὃς μονάδι μόνῃ μετρεῖται, οὗ παράδειγμα ὁ τρεῖς, ὁ πέντε, ὁ ἑπτά, καὶ τὸν τετράγωνον, τὸν τέσσαρα, τὸν ἰσάκις ἴσον, καὶ μὲν δὴ τὸν κύβον, τὸν ὀκτώ, ὅς ἐστιν ἰσάκις ἴσος ἰσάκις, καὶ τὸν τέλειον, τὸν ἕξ, ἰσούμενον τοῖς ἑαυτοῦ μέρεσι, τρισὶ καὶ δυσὶ καὶ ἑνί.", "st": "28"}, {"sp": "N", "t": "τί δὲ δεῖ καταλέγεσθαι τὰς δεκάδος ἀρετὰς ἀπείρους τὸ πλῆθος, πάρεργον ποιουμένους ἔργον μέγιστον, ὃ καθ’ αὑτὸ συμβέβηκεν αὐταρκεστάτην εἶναι ὑπόθεσιν τοῖς περὶ τὰ μαθήματα διατρίβουσι; τὰς μὲν οὖν ἄλλας ὑπερθετέον, μιᾶς δ’ οὐκ ἄτοπον ἴσως ἐπιμνησθῆναι δείγματος ἕνεκα.", "st": "29"}, {"sp": "N", "t": "τὰς γὰρ ἐν τῇ φύσει λεγομένας κατηγορίας δέκα μόνας εἶναί φασιν οἱ ἐνδιατρίβοντες τοῖς τῆς φιλοσοφίας δόγμασιν· οὐσίαν, ποιόν, ποσόν, πρός τι, ποιεῖν, πάσχειν, ἔχειν, κεῖσθαι, τὰ ὧν οὐκ ἄνευ πάντα, χρόνον καὶ τόπον.", "st": "30"}, {"sp": "N", "t": "οὐδὲν γάρ ἐστι τούτων ἀμέτοχον· οἷον ἐγὼ μετέχω μὲν οὐσίας δανεισάμενος ἀφ’ ἑκάστου τῶν στοιχείων, ἐξ ὧν ἀπετελέσθη ὅδε ὁ κόσμος, γῆς καὶ ὕδατος καὶ ἀέρος καὶ πυρός, τὰ πρὸς τὴν ἐμὴν σύστασιν αὐταρκέστατα· μετέχω δὲ καὶ ποιότητος, καθ’ ἣν ἄνθρωπός εἰμι, καὶ ποσότητος, ᾗ πηλίκος· γίνομαι δὲ καὶ πρός τι, ὅταν μου πρὸς δεξιοῖς τις ἢ πρὸς εὐωνύμοις ᾖ· ἀλλὰ καὶ ποιῶ, τρίβων τι ἢ κείρων, καὶ πάσχω, κειρόμενος ἢ τριβόμενος ὑφ’ ἑτέρων· κἀν τῷ ἔχειν ἐξετάζομαι, ἢ περιβεβλημένος ἢ ὡπλισμένος, κἀν τῷ κεῖσθαι, σχεδόν τι καθεζόμενος ἢ κατακεκλιμένος· εἰμὶ δὲ πάντως κἀν τόπῳ καὶ χρόνῳ, τῶν προειρημένων οὐδενὸς δυναμένου χωρὶς ἀμφοῖν ὑφίστασθαι.", "st": "31"}, {"sp": "N", "t": "Ταυτὶ μὲν οὖν ἀποχρώντως λελέχθω, συνυφαίνειν δ’ ἀναγκαῖον τὰ ἀκόλουθα. τοὺς δέκα λόγους ἢ χρησμούς, νόμους ἢ θεσμοὺς πρὸς ἀλήθειαν ὄντας, ἀθροισθέντος τοῦ ἔθνους ἀνδρῶν ὁμοῦ καὶ γυναικῶν εἰς ἐκκλησίαν, ὁ πατὴρ τῶν ὅλων ἐθέσπισεν. ἆρά γε φωνῆς τρόπον προέμενος αὐτός; ἄπαγε, μηδ’ εἰς νοῦν ποτ’ ἔλθοι τὸν ἡμέτερον· οὐ γὰρ ὡς ἄνθρωπος ὁ θεός, στόματος καὶ γλώττης καὶ ἀρτηριῶν δεόμενος.", "st": "32"}, {"sp": "N", "t": "ἀλλά γέ μοι δοκεῖ κατ’ ἐκεῖνον τὸν χρόνον ἱεροπρεπέστατόν τι θαυματουργῆσαι κελεύσας ἦχον ἀόρατον ἐν ἀέρι δημιουργηθῆναι, πάντων ὀργάνων θαυμασιώτερον, ἁρμονίαις τελείαις ἡρμοσμένον, οὐκ ἄψυχον ἀλλ’ οὐδ’ ἐκ σώματος καὶ ψυχῆς τρόπον ζῴου συνεστηκότα, ἀλλὰ ψυχὴν λογικὴν ἀνάπλεω σαφηνείας καὶ τρανότητος, ἣ τὸν ἀέρα σχηματίσασα καὶ ἐπιτείνασα καὶ πρὸς πῦρ φλογοειδὲς μεταβαλοῦσα καθάπερ πνεῦμα διὰ σάλπιγγος φωνὴν τοσαύτην ἔναρθρον ἐξήχησεν, ὡς τοῖς ἔγγιστα τοὺς πορρωτάτω κατ’ ἴσον ἀκροᾶσθαι δοκεῖν.", "st": "33"}, {"sp": "N", "t": "ἀνθρώπων μὲν γὰρ αἱ φωναὶ πρὸς μήκιστον ἀποτεινόμεναι πεφύκασιν ἐξασθενεῖν, ὡς ἀριδήλους τοῖς μακρὰν ἀφεστηκόσι μὴ γίνεσθαι τὰς ἀντιλήψεις ταῖς ἐπεκτάσεσιν ἐκ τοῦ κατ’ ὀλίγον ἀμαυρουμένας, ἐπειδὴ καὶ τὰ ὄργανα φθαρτά·", "st": "34"}, {"sp": "N", "t": "τὴν δὲ κεκαινουργημένην φωνὴν ἐπιπνέουσα θεοῦ δύναμις ἤγειρε καὶ ἐζωπύρει καὶ ἀναχέουσα πάντῃ τὸ τέλος τῆς ἀρχῆς ἀπέφαινε τηλαυγέστερον, ἀκοὴν ἑτέραν πολὺ βελτίω τῆς δι’ ὤτων ταῖς ἑκάστων ψυχαῖς ἐντιθεῖσα· ἡ μὲν γὰρ βραδυτέρα πως οὖσα αἴσθησις ἀτρεμίζει, μέχρις ἂν ὑπ’ ἀέρος πληχθεῖσα διακινηθῇ, φθάνει δ’ ἡ τῆς ἐνθέου διανοίας ὀξυτάτῳ τάχει προϋπαντῶσα τοῖς λεγομένοις.", "st": "35"}, {"sp": "N", "t": "Φωνῆς μὲν δὴ τῆς θείας πέρι τοσαῦτα. δεόντως δ’ ἄν τις ἀπορήσαι, τοῦ χάριν, πλείστων ὅσων μυριάδων εἰς ἓν ἠθροισμένων χωρίον, ἕκαστον θεσπίζειν τῶν δέκα λογίων ἠξίωσεν ὡς οὐχὶ πρὸς πλείους ἀλλ’ ὡς πρὸς ἕνα, “οὐ μοιχεύσεις” λέγων, “οὐ φονεύσεις,” “οὐ κλέψεις” καὶ τὰ ἄλλα ταύτῃ.", "st": "36"}, {"sp": "N", "t": "λεκτέον οὖν ἓν μέν, ὅτι βούλεται κάλλιστον ἀναδιδάξαι μάθημα τοὺς ἐντυγχάνοντας ταῖς ἱεραῖς γραφαῖς, ὡς ἄρα καθ’ αὑτὸν εἷς ἕκαστος, ὅταν ᾖ νόμιμος καὶ θεῷ καταπειθής, ἰσότιμός ἐστιν ὅλῳ ἔθνει πολυανθρωποτάτῳ, μᾶλλον δὲ καὶ πᾶσιν ἔθνεσιν, εἰ δὲ δεῖ περαιτέρω προελθόντα εἰπεῖν, καὶ παντὶ τῷ κόσμῳ.", "st": "37"}, {"sp": "N", "t": "διόπερ ἐν ἑτέροις ἐπαινῶν τινα δίκαιον ἄνδρα φησίν· “ἐγώ εἰμι ὁ θεὸς σός”· ὁ δ’ αὐτὸς ἦν καὶ κόσμου θεός, ὡς τοὺς ὑπηκόους τὴν αὐτὴν τεταγμένους τάξιν καὶ ὁμοίως εὐαρεστοῦντας τῷ ταξιάρχῳ τῆς ἴσης ἀποδοχῆς καὶ τιμῆς μεταλαμβάνειν.", "st": "38"}, {"sp": "N", "t": "δεύτερον δέ, ὅτι κοινῇ μὲν ὡς πλήθει τις ἐκκλησιάζων οὐκ ἐξ ἀνάγκης διαλέγεται ἑνί, ὅτε δὲ προστάττων ἢ ἀπαγορεύων, ἰδίᾳ ὡς ἑνὶ ἑκάστῳ τῶν ἐμφερομένων εὐθὺς ἂν δόξαι τὰ πρακτέα καὶ κοινῇ πᾶσιν ἀθρόοις ὑφηγεῖσθαι· εὐπειθέστερος δὲ ὁ τὰς παραινέσεις αὐτοπροσώπως δεχόμενος, ὁ δὲ συλλήβδην μεθ’ ἑτέρων κεκώφωται τὸν ὄχλον ἀφηνιασμοῦ παρακάλυμμα ποιούμενος.", "st": "39"}, {"sp": "N", "t": "τρίτον, ἵνα μηδείς ποτε βασιλεὺς ἢ τύραννος ἀφανοῦς ἰδιώτου καταφρονήσῃ γεμισθεὶς ἀλαζονείας καὶ ὑπεροψίας, ἀλλ’ εἰς τὰ τῶν ἱερῶν νόμων διδασκαλεῖα φοιτήσας χαλάσῃ τὰς ὀφρῦς, ἀπομαθὼν οἴησιν εἰκότι μᾶλλον δ’ ἀληθεῖ λογισμῷ.", "st": "40"}, {"sp": "N", "t": "εἰ γὰρ ὁ ἀγένητος καὶ ἄφθαρτος καὶ ἀίδιος καὶ οὐδενὸς ἐπιδεὴς καὶ ποιητὴς τῶν ὅλων καὶ εὐεργέτης καὶ βασιλεὺς βασιλέων καὶ θεὸς θεῶν οὐδὲ τὸν ταπεινότατον ὑπεριδεῖν ὑπέμεινεν, ἀλλὰ καὶ τοῦτον εὐωχῆσαι λογίων καὶ θεσμῶν ἱερῶν ἠξίωσεν, ὡς μόνον ἑστιᾶν μέλλων καὶ μόνῳ τὸ συμπόσιον εὐτρεπίζεσθαι πρὸς ψυχῆς ἀνάχυσιν ἱεροφαντουμένης, ᾗ θέμις τὰς μεγάλας τελεῖσθαι τελετάς, ἐμοὶ τῷ θνητῷ τί προσῆκον ὑψαυχενεῖν καὶ πεφυσῆσθαι φρυαττομένῳ πρὸς τοὺς ὁμοίους, οἳ τύχαις μὲν ἀνίσοις ἴσῃ δὲ καὶ ὁμοίᾳ συγγενείᾳ κέχρηνται μίαν ἐπιγραψάμενοι μητέρα τὴν κοινὴν ἁπάντων ἀνθρώπων φύσιν;", "st": "41"}, {"sp": "N", "t": "εὐπρόσιτον οὖν καὶ εὐέντευκτον ἐμαυτὸν παρέξω, κἂν τὸ τῆς γῆς καὶ τῆς θαλάττης κράτος ἀνάψωμαι, τοῖς ἀπορωτάτοις καὶ ἀδοξοτάτοις καὶ οἰκειοτάτης συμμαχίας ἐρήμοις, ἑκατέρου τῶν γονέων ὀρφανοῖς καὶ γυναιξὶ χηρείαν ὑπομενούσαις καὶ πρεσβύταις ἢ μὴ παιδοποιησαμένοις τὸ παράπαν ἢ ἀποβαλοῦσιν ὠκυμόρους οὓς ἐγέννησαν.", "st": "42"}, {"sp": "N", "t": "ἄνθρωπος γὰρ ὢν ὄγκον καὶ σεμνότητα τετραγῳδημένην οὐ δικαιώσω προσίεσθαι, μενῶ δ’ ἐντὸς τῆς φύσεως τοὺς ὅρους αὐτῆς μὴ ὑπερβαίνων, ἀλλ’ ἐθίζων τὴν ἐμαυτοῦ διάνοιαν ἀνθρωποπαθεῖν, οὐ μόνον διὰ τὰς ἀδήλους πρὸς τἀναντία μεταβολὰς καὶ τῶν εὖ πραττόντων καὶ τῶν ἐν κακοπραγίαις, ἀλλὰ καὶ διὰ τὸ ἁρμόττειν, κἂν ἀτρέπτως καὶ βεβαίως παραμένῃ τὸ εὐτυχεῖν, μὴ ἐπιλανθάνεσθαί τινα ἑαυτοῦ. διὰ ταῦτά μοι δοκεῖ τοὺς χρησμοὺς ἑνικῶς ἀποτεινάμενος ὡς πρὸς ἕνα θεσπίζειν ἐθελῆσαι.", "st": "43"}, {"sp": "N", "t": "Πάντα δ’ ὡς εἰκὸς τὰ περὶ τὸν τόπον ἐθαυματουργεῖτο, κτύποις βροντῶν μειζόνων ἢ ὥστε χωρεῖν ἀκοάς, ἀστραπῶν λάμψεσιν αὐγοειδεστάταις, ἀοράτου σάλπιγγος ἠχῇ πρὸς μήκιστον ἀποτεινούσῃ, καθόδῳ νεφέλης, ἣ κίονος τρόπον τὴν μὲν βάσιν ἐπὶ γῆς ἠρήρειστο, τὸ δ’ ἄλλο σῶμα πρὸς αἰθέριον ὕψος ἀνέτεινε, πυρὸς οὐρανίου φορᾷ καπνῷ βαθεῖ τὰ ἐν κύκλῳ συσκιάζοντος· ἔδει γὰρ θεοῦ δυνάμεως ἀφικνουμένης μηδὲν τῶν τοῦ κόσμου μερῶν ἡσυχάζειν, ἀλλὰ πάντα πρὸς ὑπηρεσίαν συγκεκινῆσθαι.", "st": "44"}, {"sp": "N", "t": "παρειστήκει δὲ ὁ λεὼς ἁγνεύσας ὁμιλιῶν τῶν πρὸς γυναῖκας καὶ πασῶν ἡδονῶν ἔξω τῶν πρὸς τροφὰς ἀναγκαίων ἀποσχόμενος, λουτροῖς τε καὶ περιρραντηρίοις καθηράμενος ἐκ τριῶν ἡμερῶν, ἔτι καὶ τὰς ἐσθῆτας ἀποπλυνάμενος, ἐν τοῖς μάλιστα λευχείμων, ἀκροβατῶν καὶ ἀνωρθιακὼς τὰ ὦτα, Μωυσέως προδηλώσαντος εὐτρεπίζεσθαι πρὸς ἐκκλησίαν· ἔγνω γὰρ αὐτὴν ἐσομένην, ἡνίκα μόνος ἀνακληθεὶς ἐχρησμῳδεῖτο.", "st": "45"}, {"sp": "N", "t": "φωνὴ δ’ ἐκ μέσου τοῦ ῥυέντος ἀπ’ οὐρανοῦ πυρὸς ἐξήχει καταπληκτικωτάτη, τῆς φλογὸς εἰς διάλεκτον ἀρθρουμένης τὴν συνήθη τοῖς ἀκροωμένοις, ᾗ τὰ λεγόμενα οὕτως ἐναργῶς ἐτρανοῦτο, ὡς ὁρᾶν αὐτὰ μᾶλλον ἢ ἀκούειν δοκεῖν.", "st": "46"}, {"sp": "N", "t": "ἐγγυᾶται δέ μου τὸν λόγον ὁ νόμος, ἐν ᾧ γέγραπται· “πᾶς ὁ λαὸς ἑώρα τὴν φωνήν”· ἐμφαντικώτατα· τὴν μὲν γὰρ ἀνθρώπων ἀκουστὴν εἶναι συμβέβηκεν, ὁρατὴν δὲ ὡς ἀληθῶς τὴν θεοῦ. διὰ τί; ὅτι ὅσα ἂν λέγῃ ὁ θεός, οὐ ῥήματά ἐστιν ἀλλ’ ἔργα, ἅπερ ὀφθαλμοὶ πρὸ ὤτων δικάζουσι.", "st": "47"}, {"sp": "N", "t": "παγκάλως μέντοι καὶ θεοπρεπῶς εἴρηται ἐκ τοῦ πυρὸς ἡ φωνὴ προέρχεσθαι· ἠκρίβωται γὰρ καὶ βεβασάνισται τὰ τοῦ θεοῦ λόγια καθάπερ χρυσὸς πυρί. μηνύει δὲ καὶ διὰ συμβόλου τι τοιοῦτον·", "st": "48"}, {"sp": "N", "t": "ἐπειδὴ τοῦ πυρὸς τὸ μὲν φωτίζειν τὸ δὲ καίειν πέφυκεν, οἱ μὲν τοῖς χρησμοῖς ἀξιοῦντες εἶναι καταπειθεῖς ὡς ἐν ἀσκίῳ φωτὶ τὸν ἀεὶ χρόνον βιώσονται τοὺς νόμους αὐτοὺς ἀστέρας ἔχοντες ἐν ψυχῇ φωσφοροῦντας, ὅσοι δ’ ἀφηνιασταί, καιόμενοι καὶ κατακαιόμενοι διατελοῦσιν ὑπὸ τῶν ἔνδον ἐπιθυμιῶν, αἳ φλογὸς τρόπον πορθήσουσι τὸν σύμπαντα τῶν ἐχόντων βίον.", "st": "49"}, {"sp": "N", "t": "Ἃ μὲν οὖν ἀναγκαῖον ἦν προδηλῶσαι, ταῦτ’ ἐστίν. ἐπ’ αὐτὰ δὲ ἤδη τρεπτέον τὰ λόγια καὶ πάντα τὰ ἐν τούτοις ἐρευνητέον διάφορα. δέκα τοίνυν ὄντα διένειμεν εἰς δύο πεντάδας, ἃς δυσὶ στήλαις ἐνεχάραξε, καὶ ἡ μὲν προτέρα πεντὰς τὰ πρωτεῖα ἔλαχεν, ἡ δ’ ἑτέρα δευτερείων ἠξιοῦτο· καλαὶ δ’ ἀμφότεραι καὶ βιωφελεῖς, εὐρείας ὁδοὺς καὶ λεωφόρους ἑνὶ τέλει περατουμένας ἀναστέλλουσαι πρὸς ἄπταιστον ψυχῆς ἐφιεμένης ἀεὶ τοῦ βελτίστου πορείαν.", "st": "50"}, {"sp": "N", "t": "ἡ μὲν οὖν ἀμείνων πεντὰς τοιάδε ἦν· περὶ μοναρχίας, ᾗ μοναρχεῖται ὁ κόσμος· περὶ ξοάνων καὶ ἀγαλμάτων καὶ συνόλως ἀφιδρυμάτων χειροκμήτων· περὶ τοῦ μὴ λαμβάνειν ἐπὶ ματαίῳ θεοῦ πρόσρησιν· περὶ τοῦ τὴν ἱερὰν ἑβδόμην ἄγειν ἱεροπρεπῶς· περὶ γονέων τιμῆς καὶ ἰδίᾳ ἑκατέρου καὶ ἀμφοτέρων κοινῇ· ὡς εἶναι τῆς μιᾶς γραφῆς τὴν μὲν ἀρχὴν θεὸν καὶ πατέρα καὶ ποιητὴν τοῦ παντός, τὸ δὲ τέλος γονεῖς, οἳ μιμούμενοι τὴν ἐκείνου φύσιν γεννῶσι τοὺς ἐπὶ μέρους. ἡ δ’ ἑτέρα πεντὰς τὰς πάσας ἀπαγορεύσεις περιέχει· μοιχείας, φόνου, κλοπῆς, ψευδομαρτυριῶν, ἐπιθυμιῶν.", "st": "51"}, {"sp": "N", "t": "Ἐπισκεπτέον δὲ μετὰ πάσης ἀκριβείας τῶν λογίων ἕκαστον μηδὲν πάρεργον αὐτῶν ποιουμένους. ἀρχὴ δ’ ἀρίστη πάντων μὲν τῶν ὄντων θεός, ἀρετῶν δ’ εὐσέβεια· περὶ ὧν ἀναγκαιότατον πρῶτον διεξελθεῖν. πλάνος τις οὐ μικρὸς τὸ πλεῖστον τῶν ἀνθρώπων γένος κατέσχηκε περὶ πράγματος, ὅπερ ἢ μόνον ἢ μάλιστα ἦν εἰκὸς ἀπλανέστατον ταῖς ἑκάστων διανοίαις ἐνιδρῦσθαι.", "st": "52"}, {"sp": "N", "t": "ἐκτεθειώκασι γὰρ οἱ μὲν τὰς τέσσαρας ἀρχάς, γῆν καὶ ὕδωρ καὶ ἀέρα καὶ πῦρ, οἱ δ’ ἥλιον καὶ σελήνην καὶ τοὺς ἄλλους πλανήτας καὶ ἀπλανεῖς ἀστέρας, οἱ δὲ μόνον τὸν οὐρανόν, οἱ δὲ τὸν σύμπαντα κόσμον· τὸν δ’ ἀνωτάτω καὶ πρεσβύτατον, τὸν γεννητήν, τὸν ἄρχοντα τῆς μεγαλοπόλεως, τὸν στρατάρχην τῆς ἀηττήτου στρατιᾶς, τὸν κυβερνήτην, ὃς οἰκονομεῖ σωτηρίως ἀεὶ τὰ σύμπαντα, παρεκαλύψαντο ψευδωνύμους προσρήσεις ἐκείνοις ἐπιφημίσαντες ἑτέρας ἕτεροι.", "st": "53"}, {"sp": "N", "t": "καλοῦσι γὰρ οἱ μὲν τὴν γῆν Κόρην, Δήμητραν, Πλούτωνα, τὴν δὲ θάλατταν Ποσειδῶνα, δαίμονας ἐναλίους ὑπάρχους αὐτῷ προσαναπλάττοντες καὶ θεραπείας ὁμίλους μεγάλους ἀρρένων τε καὶ θηλειῶν, Ἥραν δὲ τὸν ἀέρα καὶ τὸ πῦρ Ἥφαιστον καὶ ἥλιον Ἀπόλλωνα καὶ σελήνην Ἄρτεμιν καὶ ἑωσφόρον Ἀφροδίτην καὶ στίλβοντα Ἑρμῆν·", "st": "54"}, {"sp": "N", "t": "καὶ τῶν ἄλλων ἀστέρων ἑκάστου τὰς ἐπωνυμίας μυθογράφοι παρέδοσαν, οἳ πρὸς ἀπάτην ἀκοῆς εὖ τετεχνασμένα πλάσματα συνυφήναντες ἔδοξαν περὶ τὴν τῶν ὀνομάτων θέσιν κεκομψεῦσθαι·", "st": "55"}, {"sp": "N", "t": "τόν τε οὐρανὸν εἰς ἡμισφαίρια τῷ λόγῳ διχῇ διανείμαντες, τὸ μὲν ὑπὲρ γῆς, τὸ δ’ ὑπὸ γῆς, Διοσκόρους ἐκάλεσαν τὸ περὶ τῆς ἑτερημέρου ζωῆς αὐτῶν προστερατευσάμενοι διήγημα.", "st": "56"}, {"sp": "N", "t": "τοῦ γὰρ οὐρανοῦ συνεχῶς καὶ ἀπαύστως ἀεὶ κύκλῳ περιπολοῦντος, ἀνάγκη τῶν ἡμισφαιρίων ἑκάτερον ἀντιμεθίστασθαι παρ’ ἡμέραν ἄνω τε καὶ κάτω γινόμενον ὅσα τῷ δοκεῖν· ἄνω γὰρ καὶ κάτω πρὸς ἀλήθειαν οὐδὲν ἐν σφαίρᾳ, πρὸς δὲ τὴν ἡμετέραν σχέσιν αὐτὸ μόνον εἴωθε λέγεσθαι τὸ μὲν ὑπὲρ κεφαλῆς ἄνω, κάτω δὲ τοὐναντίον.", "st": "57"}, {"sp": "N", "t": "τῷ δὴ φιλοσοφεῖν ἀνόθως ἐγνωκότι καὶ ἀδόλου καὶ καθαρᾶς εὐσεβείας μεταποιουμένῳ κάλλιστον καὶ ὁσιώτατον ὑφηγεῖται παράγγελμα, μηδὲν τῶν τοῦ κόσμου μερῶν αὐτοκρατῆ θεὸν ὑπολαμβάνειν εἶναι· καὶ γὰρ γέγονε, γένεσις δὲ φθορᾶς ἀρχή, κἂν προνοίᾳ τοῦ πεποιηκότος ἀθανατίζηται, καὶ ἦν ποτε χρόνος, ὅτε οὐκ ἦν· θεὸν δὲ πρότερον οὐκ ὄντα καὶ ἀπό", "st": "58"}, {"sp": "N", "t": "τινος χρόνου γενόμενον καὶ μὴ διαιωνίζοντα λέγειν οὐ θεμιτόν. ἀλλὰ γὰρ ἔνιοι περὶ τὰς κρίσεις ἀπονοίᾳ τοσαύτῃ κέχρηνται, ὡς οὐ μόνον τὰ εἰρημένα θεοὺς νομίζειν, ἀλλὰ καὶ ἕκαστον αὐτῶν μέγιστον καὶ πρῶτον θεόν, τὸν ὄντα ὄντως ἢ οὐκ εἰδότες ἀδιδάκτῳ τῇ φύσει ἢ οὐ σπουδάζοντες μαθεῖν, ἕνεκα τοῦ μηδὲν ἔξω τῶν αἰσθητῶν ἀόρατον καὶ νοητὸν αἴτιον ὑπολαμβάνειν εἶναι, καίτοι σαφεστάτης ἐγγὺς παρακειμένης πίστεως.", "st": "59"}, {"sp": "N", "t": "ψυχῇ γὰρ ζῶντες καὶ βουλευόμενοι καὶ πάνθ’ ὅσα κατὰ τὸν ἀνθρώπινον βίον δρῶντες οὐδέποτε ψυχὴν ὀφθαλμοῖς σώματος ἴσχυσαν θεάσασθαι, καίτοι φιλοτιμηθέντες ἂν πάσας φιλοτιμίας, εἴ πως ἰδεῖν οἷόν τε ἦν τὸ ἄγαλμα τὸ πάντων ἱεροπρεπέστατον, ἀφ’ οὗ κατὰ μετάβασιν εἰκὸς ἦν ἔννοιαν τοῦ ἀγενήτου καὶ ἀιδίου λαβεῖν, ὃς ἅπαντα τὸν κόσμον ἡνιοχῶν σωτηρίως ἀόρατος ὢν κατευθύνει.", "st": "60"}, {"sp": "N", "t": "καθάπερ οὖν τοῦ μεγάλου βασιλέως τὰς τιμὰς εἴ τις τοῖς ὑπάρχοις σατράπαις ἀπένειμεν, ἔδοξεν ἂν οὐκ ἀγνωμονέστατος μόνον ἀλλὰ καὶ ῥιψοκινδυνότατος εἶναι χαριζόμενος τὰ δεσπότου δούλοις, τὸν αὐτὸν τρόπον [ἂν] τοῖς αὐτοῖς εἴ τις γεραίρει τὸν πεποιηκότα τοῖς γεγονόσιν, ἴστω πάντων ἀβουλότατος ὢν καὶ ἀδικώτατος, ἴσα διδοὺς ἀνίσοις οὐκ ἐπὶ τιμῇ τῶν ταπεινοτέρων ἀλλ’ ἐπὶ καθαιρέσει τοῦ κρείττονος.", "st": "61"}, {"sp": "N", "t": "εἰσὶ δ’ οἳ καὶ προσυπερβάλλουσιν ἀσεβείᾳ μηδὲ τὸ ἴσον ἀποδιδόντες, ἀλλὰ τοῖς μὲν τὰ πάντα τῶν ἐπὶ τιμῇ χαριζόμενοι, τῷ δ’ οὐδὲν νέμοντες ἀλλ’ οὐδὲ μνήμην, τὸ κοινότατον· ἐπιλήθονται γὰρ οὗ μόνον μεμνῆσθαι προσῆκον ἦν, ἐπιτηδεύοντες οἱ βαρυδαίμονες ἑκούσιον λήθην.", "st": "62"}, {"sp": "N", "t": "ἔνιοι δὲ καὶ στομάργῳ κατεχόμενοι λύττῃ τὰ δείγματα τῆς ἐνιδρυμένης ἀσεβείας εἰς μέσον προφέροντες βλασφημεῖν ἐπιχειροῦσι τὸ θεῖον, ἀκονησάμενοι κακήγορον γλῶτταν, ἅμα καὶ λυπεῖν ἐθέλοντες τοὺς εὐσεβοῦντας, οἷς ἄλεκτον καὶ ἀπαρηγόρητον εὐθὺς εἰσδύεται πένθος τὴν ὅλην πυρπολοῦν ψυχὴν δι’ ὤτων· ἡ γὰρ τῶν ἀνοσίων ἑλέπολις τοῦτ’ ἐστίν, ᾧ μόνῳ τοὺς φιλοθέους ἐπιστομίζουσι νομίζοντας ὑπὲρ τοῦ μὴ παροξύνειν ἐν τῷ παρόντι κάλλιστον ἡσυχίαν.", "st": "63"}, {"sp": "N", "t": "πᾶσαν οὖν τὴν τοιαύτην τερθρείαν ἀπωσάμενοι τοὺς ἀδελφοὺς φύσει μὴ προσκυνῶμεν, εἰ καὶ καθαρωτέρας καὶ ἀθανατωτέρας οὐσίας ἔλαχον — ἀδελφὰ δ’ ἀλλήλων τὰ γενόμενα καθὸ γέγονεν, ἐπεὶ καὶ πατὴρ ἁπάντων εἷς ὁ ποιητὴς τῶν ὅλων ἐστίν —, ἀλλὰ καὶ διανοίᾳ καὶ λόγῳ καὶ πάσῃ δυνάμει τῇ τοῦ ἀγενήτου καὶ ἀιδίου καὶ τῶν ὅλων αἰτίου θεραπείᾳ σφόδρα εὐτόνως καὶ ἐρρωμένως ἐπαποδυώμεθα, μὴ ὑποκατακλινόμενοι μηδ’ ὑπείκοντες ταῖς τῶν πολλῶν ἀρεσκείαις, ὑφ’ ὧν καὶ οἱ δυνάμενοι σῴζεσθαι διαφθείρονται.", "st": "64"}, {"sp": "N", "t": "Πρῶτον μὲν οὖν παράγγελμα καὶ παραγγελμάτων ἱερώτατον στηλιτεύσωμεν ἐν ἑαυτοῖς, ἕνα τὸν ἀνωτάτω νομίζειν τε καὶ τιμᾶν θεόν· δόξα δ’ ἡ πολύθεος μηδ’ ὤτων ψαυέτω καθαρῶς καὶ ἀδόλως ἀνδρὸς εἰωθότος ζητεῖν ἀλήθειαν.", "st": "65"}, {"sp": "N", "t": "ἀλλ’ ὅσοι μὲν ἡλίου καὶ σελήνης καὶ τοῦ σύμπαντος οὐρανοῦ τε καὶ κόσμου καὶ τῶν ἐν αὐτοῖς ὁλοσχερεστάτων μερῶν ὡς θεῶν πρόπολοί τε καὶ θεραπευταί, διαμαρτάνουσι μὲν — πῶς γὰρ οὔ; — τοὺς ὑπηκόους πρὸ τοῦ ἄρχοντος ἀποσεμνύνοντες, ἧττον δὲ τῶν ἄλλων ἀδικοῦσι τῶν ξύλα καὶ λίθους ἄργυρόν τε καὶ χρυσὸν καὶ τὰς παραπλησίους ὕλας μορφωσάντων ὡς φίλον ἑκάστοις, εἶτ’ ἀγαλμάτων καὶ ξοάνων καὶ τῶν ἄλλων χειροκμήτων, ὧν πλαστικὴ καὶ ζωγραφία δημιουργοὶ μεγάλα ἔβλαψαν τὸν βίον τὸν ἀνθρώπινον, καταπλησάντων τὴν οἰκουμένην.", "st": "66"}, {"sp": "N", "t": "τὸ γὰρ κάλλιστον ἔρεισμα τῆς ψυχῆς ἐξέκοψαν, τὴν περὶ τοῦ ζῶντος ἀεὶ θεοῦ προσήκουσαν ὑπόληψιν, ὥσπερ τε ἀνερμάτιστα σκάφη σαλεύουσιν ὧδε κἀκεῖσε διαφερόμενοι τὸν αἰῶνα, μηδέποτ’ εἰς λιμένα κατᾶραι μηδ’ ἐνορμίσασθαι βεβαίως ἀληθείᾳ δυνάμενοι, τυφλώττοντες περὶ τὸ θέας ἄξιον, πρὸς ὃ μόνον ὀξυδορκεῖν ἀναγκαῖον ἦν.", "st": "67"}, {"sp": "N", "t": "καί μοι δοκοῦσι τῶν τὰς τοῦ σώματος ὄψεις πεπηρωμένων ἀθλιώτερον ζῆν· ἐκεῖνοι μὲν γὰρ ἀκουσίως ἐβλάβησαν ἢ νόσον ὀφθαλμῶν χαλεπὴν ὑποστάντες ἢ πρὸς ἐχθρῶν ἐπιβουλευθέντες, οἱ δ’ ἑκουσίῳ γνώμῃ τὸ τῆς ψυχῆς ὄμμα οὐκ ἠμαύρωσαν μόνον ἀλλὰ καὶ παντελῶς ἀποβαλεῖν ἠξίωσαν.", "st": "68"}, {"sp": "N", "t": "ὅθεν τοῖς μὲν ἔλεος ὡς ἠτυχηκόσι, τοῖς δὲ κόλασις ὡς μοχθηροῖς ἕπεται δικαίως, οἳ μετὰ τῶν ἄλλων οὐδὲ τὸ προχειρότατον ἐνενόησαν, ὃ καὶ παῖς “ἔγνω νήπιος”, ὅτι τοῦ τεχνιτευθέντος ὁ τεχνίτης ἀμείνων, καὶ χρόνῳ — πρεσβύτερος γὰρ καὶ τρόπον τινὰ τοῦ δημιουργηθέντος πατήρ — καὶ δυνάμει· τὸ γὰρ δρῶν τοῦ πάσχοντος ἐπικυδέστερον.", "st": "69"}, {"sp": "N", "t": "καὶ δέον, εἴπερ ἄρα ἐξημάρτανον, τοὺς ζωγράφους αὐτοὺς καὶ ἀνδριαντοποιοὺς ὑπερβολαῖς τιμῶν ἐκτεθειωκέναι, τοὺς μὲν εἴασαν ἀφανεῖς οὐδὲν πλέον παρασχόντες, τὰ δ’ ὑπ’ ἐκείνων δημιουργηθέντα πλάσματα καὶ ζωγραφήματα θεοὺς ἐνόμισαν.", "st": "70"}, {"sp": "N", "t": "καὶ οἱ μὲν τεχνῖται πολλάκις ἄποροι καὶ ἄδοξοι κατεγήρασαν ἀτυχίαις ἐπαλλήλοις ἐναποθανόντες, τὰ δὲ τεχνιτευθέντα πορφύρᾳ καὶ χρυσῷ καὶ ταῖς ἄλλαις πολυτελείαις, ἃς πλοῦτος χορηγεῖ, σεμνοποιεῖται καὶ θεραπεύεται, οὐ πρὸς ἐλευθέρων μόνον ἀλλὰ καὶ εὐπατριδῶν καὶ τὸ σῶμα καλλίστων· ἱερέων γὰρ καὶ τὸ γένος ἐξετάζεται μετὰ πάσης ἀκριβείας, εἰ ἀνεπίληπτον, καὶ ἡ κοινωνία τῶν τοῦ σώματος μερῶν, εἰ σύμπασα ὁλόκληρος.", "st": "71"}, {"sp": "N", "t": "καὶ οὔπω τοῦτο δεινόν, καίτοι δεινὸν ὄν, ἀλλ’ ἐκεῖνο παγχάλεπον· ἤδη γάρ τινας οἶδα τῶν πεποιηκότων τοῖς πρὸς ἑαυτῶν γεγονόσιν εὐχομένους τε καὶ θύοντας, οἷς πολὺ βέλτιον ἦν ἑκατέραν τῶν χειρῶν προσκυνεῖν, εἰ δὲ μὴ βούλοιντο δόξαν φιλαυτίας ἐκτρεπόμενοι, σφύρας γοῦν καὶ ἄκμονας καὶ γραφίδας καὶ καρκίνους καὶ τὰ ἄλλα ἐργαλεῖα, δι’ ὧν ἐμορφώθησαν αἱ ὗλαι.", "st": "72"}, {"sp": "N", "t": "καίτοι πρὸς τοὺς οὕτως ἀπονοηθέντας ἄξιον παρρησιασαμένους εἰπεῖν· εὐχῶν ἀρίστην εἶναι συμβέβηκεν, ὦ γενναῖοι, καὶ τέλος εὐδαιμονίας τὴν πρὸς θεὸν ἐξομοίωσιν.", "st": "73"}, {"sp": "N", "t": "εὔχεσθε οὖν καὶ ὑμεῖς ἐξομοιωθῆναι τοῖς ἀφιδρύμασιν, ἵνα τὴν ἀνωτάτω καρπώσησθε εὐδαιμονίαν, ὀφθαλμοῖς μὴ βλέποντες, ὠσὶ μὴ ἀκούοντες, μυκτῆρσι μήτε ἀναπνέοντες μήτε ὀσφραινόμενοι, στόματι μὴ φωνοῦντες μηδὲ γευόμενοι, χερσὶ μήτε λαμβάνοντες μήτε διδόντες μήτε δρῶντες, ποσὶ μὴ βαδίζοντες, μηδ’ ἄλλῳ τινὶ τῶν μερῶν ἐνεργοῦντες, ἀλλ’ ὥσπερ ἐν εἱρκτῇ τῷ ἱερῷ φρουρούμενοι καὶ φυλαττόμενοι, μεθ’ ἡμέραν τε καὶ νύκτωρ τὸν ἀπὸ τῶν θυομένων ἀεὶ καπνὸν σπῶντες· ἓν γὰρ μόνον τοῦτ’ ἀγαθὸν προσαναπλάττετε τοῖς ἀφιδρύμασιν.", "st": "74"}, {"sp": "N", "t": "ἀλλ’ ἔγωγε νομίζω ταῦτα ἀκούοντας οὐχ ὡς ἐπ’ εὐχαῖς ἀλλ’ ὡς ἐπὶ κατάραις ἀγανακτήσειν καὶ τρέψεσθαι πρὸς λοιδορίας ἄμυναν ἀντικατηγοροῦντας· ὃ μέγιστον ἂν εἴη τεκμήριον τῆς ἐπιπολαζούσης ἀσεβείας ἀνθρώπων θεοὺς νομιζόντων, οἷς ὅμοιοί", "st": "75"}, {"sp": "N", "t": "ποτε τὰς φύσεις ἀπεύξαιντ’ ἂν γενέσθαι. μηδεὶς οὖν τῶν ἐχόντων ψυχὴν ἀψύχῳ τινὶ προσκυνείτω· πάνυ γὰρ τῶν ἀτόπων ἐστὶ τὰ φύσεως ἔργα πρὸς θεραπείαν τετράφθαι τῶν χειροκμήτων. Αἰγυπτίοις δ’ οὐ μόνον τὸ κοινὸν ἔγκλημα χώρας ἁπάσης, ἀλλὰ καὶ ἕτερον ἐξαίρετον ἐπάγεται δεόντως· πρὸς γὰρ ξοάνοις καὶ ἀγάλμασιν ἔτι καὶ ζῷα ἄλογα παραγηόχασιν εἰς θεῶν τιμάς, ταύρους καὶ κριοὺς καὶ τράγους, ἐφ’ ἑκάστῳ μυθικόν τι πλάσμα τετερατευμένοι.", "st": "76"}, {"sp": "N", "t": "καὶ ταῦτα μὲν ἴσως ἔχει τινὰ λόγον, ἡμερώτατα γὰρ καὶ ὠφελιμώτατα τῷ βίῳ· ἀροτὴρ ὁ βοῦς αὔλακας ἀνατέμνει καιρῷ σπορᾶς, ἀλοῆσαι πάλιν, ὅταν δέῃ τὸν καρπὸν καθαίρεσθαι, δυνατώτατος· ὁ κριὸς τὸ κάλλιστον τῶν σκεπασμάτων, ἐσθῆτα, παρέχει· γυμνὰ γὰρ ἂν τὰ σώματα διεφθείρετο ῥᾳδίως, ἢ διὰ θάλπος ἢ διὰ κρύος ἄμετρον, τοτὲ μὲν τῷ ἀφ’ ἡλίου φλογμῷ, τοτὲ δὲ τῇ ἀπ’ ἀέρος περιψύξει.", "st": "77"}, {"sp": "N", "t": "νυνὶ δὲ προσυπερβάλλοντες καὶ τῶν ἀνημέρων τὰ ἀγριώτατα καὶ ἀτιθασώτατα, λέοντας καὶ κροκοδείλους καὶ ἑρπετῶν τὴν ἰοβόλον ἀσπίδα, γεραίρουσιν ἱεροῖς καὶ τεμένεσι θυσίαις τε καὶ πανηγύρεσι καὶ πομπαῖς καὶ τοῖς παραπλησίοις· ἀφ’ ἑκατέρου γὰρ τῶν εἰς χρῆσιν δοθέντων ἀνθρώποις ὑπὸ θεοῦ, γῆς καὶ ὕδατος, διερευνησάμενοι τὰ ἀγριώτατα οὔτε τῶν χερσαίων λέοντος θηριωδέστερον ἀνεῦρον οὔτε κροκοδείλου τῶν ἐνύδρων ἀγριώτερον, ἃ σέβουσι καὶ τιμῶσι.", "st": "78"}, {"sp": "N", "t": "πολλὰ μέντοι καὶ ἄλλα ζῷα, κύνας, αἰλούρους, λύκους, καὶ πτηνὰ ἴβιδας καὶ ἱέρακας, καὶ πάλιν ἰχθύων ἢ ὅλα τὰ σώματα ἢ μέρη τούτων ἐκτεθειώκασιν·", "st": "79"}, {"sp": "N", "t": "ὧν τί ἂν γένοιτο καταγελαστότερον; καὶ δὴ τῶν ξένων οἱ πρῶτον εἰς Αἴγυπτον ἀφικόμενοι, πρὶν τὸν ἐγχώριον τῦφον εἰσοικίσασθαι ταῖς διανοίαις, ἐκθνῄσκουσι χλευάζοντες· ὅσοι δὲ παιδείας ὀρθῆς ἐγεύσαντο, τὴν ἐπ’ ἀσέμνοις πράγμασι σεμνοποιίαν καταπλαγέντες οἰκτίζονται τοὺς χρωμένους, ἀθλιωτέρους, ὅπερ εἰκός, ὑπολαμβάνοντες εἶναι τῶν τιμωμένων, μεταβεβληκότας εἰς ἐκεῖνα τὰς ψυχάς, ὡς ἀνθρωποειδῆ θηρία περινοστεῖν δοκεῖν.", "st": "80"}, {"sp": "N", "t": "ἀνελὼν οὖν ἐκ τῆς ἱερᾶς νομοθεσίας πᾶσαν τὴν τοιαύτην ἐκθέωσιν ἐπὶ τὴν τοῦ πρὸς ἀλήθειαν ὄντος θεοῦ τιμὴν ἐκάλεσεν, ἑαυτοῦ τιμῆς οὐ προσδεόμενος — οὐ γὰρ ἑτέρου χρεῖος ἦν ὁ αὐταρκέστατος ἑαυτῷ —, βουλόμενος δὲ τὸ γένος τῶν ἀνθρώπων ἀνοδίαις πλαζόμενον εἰς ἀπλανεστάτην ἄγειν ὁδόν, ἵν’ ἑπόμενον τῇ φύσει τὸ ἄριστον εὕρηται τέλος, ἐπιστήμην τοῦ ὄντως ὄντος, ὅς ἐστι τὸ πρῶτον ἀγαθὸν καὶ τελεώτατον, ἀφ’ οὗ τρόπον πηγῆς ἄρδεται τῷ κόσμῳ καὶ τοῖς ἐν αὐτῷ τὰ ἐπὶ μέρους ἀγαθά.", "st": "81"}, {"sp": "N", "t": "Διειλεγμένοι καὶ περὶ τῆς δευτέρας παραινέσεως ὅσα οἷόν τε ἦν, τὴν ἑπομένην κατὰ τὸ ἑξῆς ἀκριβώσωμεν· ἔστι δὲ μὴ λαμβάνειν ὄνομα θεοῦ ἐπὶ ματαίῳ. τὰ μὲν οὖν τῆς τάξεως γνώριμα τοῖς τὴν διάνοιαν ὀξυδορκοῦσιν· ὄνομα γὰρ ἀεὶ δεύτερον ὑποκειμένου πράγματος, σκιᾷ παραπλήσιον, ἣ παρέπεται σώματι.", "st": "82"}, {"sp": "N", "t": "προειπὼν οὖν περὶ τῆς ὑπάρξεως καὶ τιμῆς τοῦ ἀεὶ ὑπάρχοντος, ἑπομένως τῷ τῆς ἀκολουθίας εἱρμῷ τὰ πρέποντα καὶ περὶ τῆς κλήσεως εὐθὺς παρήγγειλε· πολύτροποι γὰρ καὶ πολυειδεῖς αἱ περὶ τοῦτο τὸ μέρος τῶν ἀνθρώπων ἁμαρτίαι.", "st": "83"}, {"sp": "N", "t": "κάλλιστον δὴ καὶ βιωφελέστατον καὶ ἁρμόττον λογικῇ φύσει τὸ ἀνώμοτον, οὕτως ἀληθεύειν ἐφ’ ἑκάστου δεδιδαγμένῃ, ὡς τοὺς λόγους ὅρκους εἶναι νομίζεσθαι. δεύτερος δέ, φασί, πλοῦς τὸ εὐορκεῖν·", "st": "84"}, {"sp": "N", "t": "ἤδη γὰρ ὅ γε ὀμνὺς εἰς ἀπιστίαν ὑπονοεῖται. μελλητὴς οὖν ἔστω καὶ βραδύς, εἴ πως ἐνδέχοιτο ταῖς ὑπερθέσεσιν ἀπώσασθαι τὸν ὅρκον· εἰ δέ τις ἀνάγκη βιάζοιτο, περισκεπτέον οὐ παρέργως ἕκαστα τῶν ἐμφερομένων·", "st": "85"}, {"sp": "N", "t": "τὸ γὰρ πρᾶγμα οὐ μικρόν, εἰ καὶ τῷ ἔθει καταφρονεῖται. μαρτυρία γάρ ἐστι θεοῦ περὶ πραγμάτων ἀμφισβητουμένων ὅρκος· μάρτυρα δὲ καλεῖν ἐπὶ ψεύδει θεὸν ἀνοσιώτατον. ἴθι γάρ, εἰ βούλει, τῷ λόγῳ διάκυψον εἰς τὴν τοῦ μέλλοντος ὀμνύναι διάνοιαν ἐπὶ ψεύδει· θεάσῃ γὰρ αὐτὴν οὐκ ἠρεμοῦσαν, ἀλλὰ θορύβου καὶ ταραχῆς μεστήν, κατηγορουμένην καὶ πάσας ὕβρεις καὶ βλασφημίας ὑπομένουσαν.", "st": "86"}, {"sp": "N", "t": "ὁ γὰρ ἑκάστῃ ψυχῇ συμπεφυκὼς καὶ συνοικῶν ἔλεγχος, οὐδὲν εἰωθὼς παραδέχεσθαι τῶν ὑπαιτίων, μισοπονήρῳ καὶ φιλαρέτῳ χρώμενος ἀεὶ τῇ φύσει, κατήγορος ὁμοῦ καὶ δικαστὴς ὁ αὐτὸς ὤν, διακινηθεὶς ὡς μὲν κατήγορος αἰτιᾶται, κατηγορεῖ, δυσωπεῖ, πάλιν δ’ ὡς δικαστὴς διδάσκει, νουθετεῖ, παραινεῖ μεταβάλλεσθαι· κἂν μὲν ἰσχύσῃ πεῖσαι, γεγηθὼς καταλλάττεται, μὴ δυνηθεὶς δὲ ἀσπονδεὶ πολεμεῖ μήτε μεθ’ ἡμέραν μήτε νύκτωρ ἀφιστάμενος, ἀλλὰ κεντῶν καὶ τιτρώσκων ἀνίατα, μέχρις ἂν τὴν ἀθλίαν καὶ ἐπάρατον ζωὴν ἀπορρήξῃ.", "st": "87"}, {"sp": "N", "t": "τί λέγεις, εἴποιμ’ ἂν πρὸς τὸν ἐπίορκον, τολμήσεις τινὶ τῶν σεαυτοῦ γνωρίμων φάναι προσελθών· ὦ οὗτος, ἃ μήτ’ εἶδες μήτ’ ἤκουσας, ὡς ἰδών, ὡς ἀκούσας, ὡς παρηκολουθηκὼς ἅπασιν, ἀφικόμενός μοι μαρτύρησον; ἐγὼ μέν γε οὐκ οἶμαι·", "st": "88"}, {"sp": "N", "t": "μανίας γὰρ ἀθεραπεύτου τὸ ἔργον. ἐπεὶ τίσιν ὀφθαλμοῖς νήφων καὶ ἐν σεαυτῷ δοκῶν εἶναι προσιδὼν τὸν φίλον ἐρεῖς· διὰ τὴν ἑταιρίαν ἀδικοπράγει, παρανόμει, συνασέβει μοι; δῆλον γὰρ ὡς, εἰ ταῦτ’ ἀκούσαι, πολλὰ χαίρειν φράσας ἑταιρίᾳ τῇ νομιζομένῃ καὶ κακίσας αὑτόν, ὅτι τὴν ἀρχὴν ἀνδρὶ τοιούτῳ φιλίας ἐκοινώνησεν, ἀποπηδήσεται καθάπερ ἀπὸ θηρὸς ἀγριαίνοντος καὶ λελυττηκότος.", "st": "89"}, {"sp": "N", "t": "εἶτα, πρὸς ἃ μηδὲ φίλον ἄγειν τολμήσεις, ἐπὶ ταῦτα θεὸν μάρτυρα καλῶν οὐκ ἐρυθριᾷς, τὸν πατέρα καὶ ἡγεμόνα τοῦ κόσμου; πότερον ἐπιστάμενος, ὅτι πάνθ’ ὁρᾷ καὶ πάντων ἀκούει, ἢ τοῦτ’ ἀγνοῶν;", "st": "90"}, {"sp": "N", "t": "εἰ μὲν οὖν ἀγνοῶν, ἄθεός τις εἶ, πηγὴ δὲ πάντων ἀδικημάτων ἀθεότης· πρὸς δὲ τῷ ἀθέῳ καὶ καταστρατηγεῖς τὸν ὅρκον, ὀμνὺς κατὰ τοῦ μὴ προσέχοντος ὡς ἐπιμελουμένου τῶν ἀνθρωπείων πραγμάτων· εἰ δ’ ὅτι προνοεῖ σαφῶς οἶδας, ὑπερβολὴν ἀσεβείας οὐκ ἀπολέλοιπας λέγων, εἰ καὶ μὴ στόματι καὶ γλώττῃ, τῷ γοῦν συνειδότι πρὸς θεόν· τὰ ψευδῆ μοι μαρτύρει, συγκακούργει, συρρᾳδιούργει· μία μοι τοῦ παρ’ ἀνθρώποις εὐδοκιμεῖν ἐλπὶς τὸ παρακαλύψασθαί σε τὴν ἀλήθειαν· ὑπὲρ ἑτέρου πονηρὸς γενοῦ, ὑπὲρ τοῦ χείρονος ὁ κρείττων, ὑπὲρ ἀνθρώπου καὶ ταῦτα", "st": "91"}, {"sp": "N", "t": "μοχθηροῦ θεὸς ὁ πάντων ἄριστος. εἰσὶ δ’ οἳ μηδὲ κερδαίνειν τι μέλλοντες ἔθει πονηρῷ κατακόρως καὶ ἀνεξετάστως ὀμνύουσιν ἐπὶ τοῖς τυχοῦσιν, οὐδενὸς ἀμφισβητουμένου τὸ παράπαν, τὰ μὲν αὐτῶν ἐν τῷ λόγῳ προσαναπληροῦντες ὅρκοις, ὡς οὐκ ἄμεινον ὂν ἀποκοπὴν ῥημάτων μᾶλλον δὲ καὶ ἀφωνίαν ὑποστῆναι παντελῆ· φύεται γὰρ ἐκ πολυορκίας ψευδορκία καὶ ἀσέβεια.", "st": "92"}, {"sp": "N", "t": "διὸ χρὴ τὸν μέλλοντα ὀμνύναι πάντ’ ἐπιμελῶς ἐξητακέναι καὶ σφόδρα περιττῶς, τὸ πρᾶγμα, εἰ εὐμέγεθες καὶ εἰ γέγονεν ὄντως καὶ εἰ πραχθὲν κατείληφε παγίως, ἑαυτόν, εἰ καθαρεύει ψυχὴν καὶ σῶμα καὶ γλῶτταν, τὴν μὲν παρανομίας, τὸ δὲ μιασμάτων, τὴν δὲ βλασφημιῶν· οὐ γὰρ ὅσιον, δι’ οὗ στόματος τὸ ἱερώτατον ὄνομα προφέρεταί τις, διὰ τούτου φθέγγεσθαί τι τῶν αἰσχρῶν.", "st": "93"}, {"sp": "N", "t": "ἐρευνάτω δὲ καὶ τόπον καὶ καιρὸν ἐπιτήδειον· οἶδα γὰρ οἶδά τινας ἐν βεβήλοις καὶ ἀκαθάρτοις χωρίοις, ἐν οἷς οὔτε πατρὸς οὔτε μητρὸς ἀλλ’ οὐδὲ τῶν ὀθνείων πρεσβύτου τινὸς εὖ βεβιωκότος ἄξιον μεμνῆσθαι, διομνυμένους καὶ ὅλας ῥήσεις ὅρκων συνείροντας, τῷ τοῦ θεοῦ πολυωνύμῳ καταχρησαμένους ὀνόματι ἔνθα μὴ δεῖ πρὸς ἀσέβειαν.", "st": "94"}, {"sp": "N", "t": "ὁ δὲ τῶν λεχθέντων ὀλιγώρως ἔχων ἴστω τὸ μὲν πρῶτον μιαρὸς καὶ ἀκάθαρτος ὤν, εἶθ’ ὡς αἰεὶ αἱ μέγισται τῶν τιμωριῶν ἐφεδρεύουσιν αὐτῷ, τῆς ἐφόρου τῶν ἀνθρωπείων δίκης ἀτρέπτως καὶ ἀπαρηγορήτως ἐπὶ τοῖς οὕτω μεγάλοις ἀδικήμασιν ἐχούσης, ἥτις, ὅταν μὴ παραχρῆμα κολάζειν ἀξιοῖ, ἐπὶ πολλῷ δανείζειν ἔοικε τὰς τιμωρίας, ἅς, ὅταν ᾖ καιρός, ἀναπράττει μετὰ τοῦ κοινῇ συμφέροντος.", "st": "95"}, {"sp": "N", "t": "Τέταρτόν ἐστι παράγγελμα τὸ περὶ τῆς ἱερᾶς ἑβδόμης, ἵν’ εὐαγῶς καὶ ὁσίως ἄγηται. ταύτην ἔνιαι μὲν τῶν πόλεων ἑορτάζουσιν ἅπαξ τοῦ μηνὸς ἀπὸ τῆς κατὰ θεὸν νουμηνίας διαριθμούμεναι, τὸ δὲ Ἰουδαίων ἔθνος συνεχῶς ἡμέρας ἓξ διαλείποντες αἰεί.", "st": "96"}, {"sp": "N", "t": "λόγος δ’ ἐστὶν ἀναγραφεὶς ἐν τοῖς κατὰ τὴν κοσμοποιίαν, περιέχων αἰτίαν ἀναγκαίαν· ἐν γὰρ ἓξ ἡμέραις φησὶ κτισθῆναι τὸν κόσμον, τῇ δ’ ἑβδόμῃ παυσάμενον τῶν ἔργων τὸν θεὸν ἄρξασθαι τὰ γεγονότα καλῶς θεωρεῖν.", "st": "97"}, {"sp": "N", "t": "ἐκέλευσεν οὖν καὶ τοὺς μέλλοντας ἐν ταύτῃ ζῆν τῇ πολιτείᾳ καθάπερ ἐν τοῖς ἄλλοις καὶ κατὰ τοῦθ’ ἕπεσθαι θεῷ, πρὸς μὲν ἔργα τρεπομένους ἐφ’ ἡμέρας ἕξ, ἀνέχοντας δὲ τῇ ἑβδόμῃ καὶ φιλοσοφοῦντας καὶ θεωρίαις μὲν τῶν τῆς φύσεως σχολάζοντας, ἐπισκοποῦντας δὲ καὶ εἴ τι μὴ καθαρῶς ἐν ταῖς προτέραις ἐπράχθη, λόγον καὶ εὐθύνας ὧν εἶπον ἢ ἔδρασαν παρ’ ἑαυτῶν λαμβάνοντας ἐν τῷ τῆς ψυχῆς βουλευτηρίῳ, συνεδρευόντων καὶ συνεξεταζόντων τῶν νόμων εἴς τε τὴν τῶν παροραθέντων κατόρθωσιν καὶ πρὸς τὴν τοῦ μηδὲν αὖθις ἐξαμαρτάνειν προφυλακήν.", "st": "98"}, {"sp": "N", "t": "ἀλλ’ ὁ μὲν θεὸς ἅπαξ κατεχρήσατο ταῖς ἓξ ἡμέραις πρὸς τὴν τοῦ κόσμου τελείωσιν μήκους χρόνων οὐ προσδεόμενος· ἀνθρώπων δ’ ἕκαστος ἅτε θνητῆς φύσεως μετέχων καὶ μυρίων ἐνδεὴς ὢν πρὸς τὰς ἀναγκαίας τοῦ βίου χρείας ὀφείλει μὴ κατοκνεῖν ἐκπορίζειν τὰ ἐπιτήδεια μέχρι τελευτῆς τοῦ βίου διαναπαυόμενος τὰς ἱερὰς ἑβδομάδας.", "st": "99"}, {"sp": "N", "t": "ἆρ’ οὐ παγκάλη παραίνεσις καὶ πρὸς πᾶσαν ἀρετὴν ἱκανωτάτη προτρέψασθαι καὶ διαφερόντως εἰς εὐσέβειαν; “ἕπου” φησίν “αἰεὶ θεῷ· παράδειγμα προθεσμίας ἔστω σοι πράξεων ἓν ἑξαήμερον αὐταρκέστατον, ἐν ᾧ τὸν κόσμον ἐδημιούργει· παράδειγμα καὶ τοῦ δεῖν φιλοσοφεῖν ἡ ἑβδόμη, καθ’ ἣν ἐπιδεῖν λέγεται ἃ εἰργάσατο, ὅπως καὶ αὐτὸς ἐπιθεωρῇς τὰ φύσεως καὶ τὰ ἴδια ὅσα συντείνει πρὸς εὐδαιμονίαν”.", "st": "100"}, {"sp": "N", "t": "τοιοῦτον οὖν ἀρχέτυπον τῶν ἀρίστων βίων, πρακτικοῦ τε καὶ θεωρητικοῦ, μὴ παρέλθωμεν, ἀλλ’ αἰεὶ πρὸς αὐτὸ βλέποντες ἐναργεῖς εἰκόνας καὶ τύπους ταῖς ἑαυτῶν διανοίαις ἐγχαράττωμεν ἐξομοιοῦντες θνητὴν φύσιν ὡς ἔνεστιν ἀθανάτῳ κατὰ τὸ λέγειν καὶ πράττειν ἃ χρή. πῶς δὲ λέγεται ἐν ἓξ ἡμέραις γεγενῆσθαι τὸν κόσμον ὑπὸ θεοῦ τοῦ μηδὲ χρόνων εἰς τὸ ποιεῖν δεομένου, μεμήνυται διὰ τῶν ἀλληγορηθέντων", "st": "101"}, {"sp": "N", "t": "ἐν ἑτέροις. τὴν μέντοι προνομίαν, ἧς ἐν τοῖς οὖσιν ἑβδομὰς ἠξίωται, δηλοῦσιν οἱ περὶ τὰ μαθήματα διατρίψαντες, ἐπιμελῶς πάνυ καὶ πεφροντισμένως αὐτὴν ἐξιχνεύσαντες. ἥδε γάρ ἐστιν ἡ ἐν ἀριθμοῖς παρθένος, ἡ ἀμήτωρ φύσις, ἡ μονάδος οἰκειοτάτη καὶ ἀρχῆς, ἡ ἰδέα τῶν πλανήτων, ἐπεὶ καὶ τῆς ἀπλανοῦς σφαίρας μονάς· ἐκ γὰρ μονάδος καὶ ἑβδομάδος οὐρανὸς ὁ ἀσώματος, τὸ παράδειγμα τοῦ ὁρατοῦ.", "st": "102"}, {"sp": "N", "t": "πέπηγε δ’ ὁ οὐρανὸς ἔκ τε τῆς ἀμερίστου φύσεως καὶ τῆς μεριστῆς· ἡ μὲν οὖν ἀμέριστος τὴν πρώτην καὶ ἀνωτάτω καὶ ἀπλανῆ περιφορὰν εἴληχεν, ἣν μονὰς ἐπισκοπεῖ, ἡ δὲ μεριστὴ τὴν καὶ δυνάμει καὶ τάξει δευτέραν, ἧς ἐπιτροπεύει ἑβδομάς, ἥτις ἑξαχῇ διανεμηθεῖσα τοὺς ἐπικαλουμένους ἑπτὰ πλάνητας εἰργάσατο·", "st": "103"}, {"sp": "N", "t": "οὐκ ἐπειδὴ πεπλάνηταί τι τῶν κατὰ τὸν οὐρανὸν θείας καὶ μακαρίας καὶ εὐδαίμονος φύσεως μετεσχηκότων, οἷς πᾶσι τὸ ἀπλανὲς οἰκειότατον — τὴν γοῦν ἐν ὁμοίῳ ταυτότητα σῴζοντα δολιχεύει τὸν αἰῶνα μηδεμίαν ἐνδεχόμενα τροπὴν καὶ μεταβολήν —, ἀλλ’ ὅτι περιπολοῦνται ὑπεναντίως τῇ ἀμερίστῳ καὶ ἐξωτάτω σφαίρᾳ, πλάνητες ὠνομάσθησαν οὐ κυρίως ὑπ’ ἀνθρώπων εἰκαιοτέρων, οἳ τὴν ἰδίαν πλάνην τοῖς οὐρανίοις ἐπεφήμισαν, ἃ τὴν τοῦ θείου στρατοπέδου τάξιν οὐδέποτε λείπει.", "st": "104"}, {"sp": "N", "t": "διὰ μὲν δὴ ταῦτα καὶ ἔτι πλείω τετίμηται ἡ ἑβδομάς· ἐπ’ οὐδενὶ δ’ οὕτω προνομίας ἔτυχεν ἢ τῷ μάλιστα τὸν ποιητὴν καὶ πατέρα τῶν ὅλων ἐμφαίνεσθαι δι’ αὐτῆς· ὡς γὰρ διὰ κατόπτρου φαντασιοῦται ὁ νοῦς θεὸν δρῶντα καὶ κοσμοποιοῦντα καὶ τῶν ὅλων ἐπιτροπεύοντα.", "st": "105"}, {"sp": "N", "t": "Μετὰ δὲ τὰ περὶ τῆς ἑβδόμης παραγγέλλει πέμπτον παράγγελμα τὸ περὶ γονέων τιμῆς τάξιν αὐτῷ δοὺς τὴν μεθόριον τῶν δυοῖν πεντάδων· τελευταῖον γὰρ ὂν τῆς προτέρας, ἐν ᾗ τὰ ἱερώτατα προστάττεται, συνάπτει καὶ τῇ δευτέρᾳ περιεχούσῃ τὰ πρὸς ἀνθρώπους δίκαια.", "st": "106"}, {"sp": "N", "t": "αἴτιον δ’ ὡς οἶμαι τόδε· τῶν γονέων ἡ φύσις ἀθανάτου καὶ θνητῆς οὐσίας ἔοικεν εἶναι μεθόριος, θνητῆς μὲν διὰ τὴν πρὸς ἀνθρώπους καὶ τὰ ἄλλα ζῷα συγγένειαν κατὰ τὸ τοῦ σώματος ἐπίκηρον, ἀθανάτου δὲ διὰ τὴν τοῦ γεννᾶν πρὸς θεὸν τὸν γεννητὴν τῶν ὅλων ἐξομοίωσιν.", "st": "107"}, {"sp": "N", "t": "ἤδη μὲν οὖν τινες τῇ ἑτέρᾳ μερίδι προσκληρώσαντες ἑαυτοὺς ἔδοξαν τῆς ἑτέρας ὀλιγωρεῖν· ἄκρατον γὰρ ἐμφορησάμενοι τὸν εὐσεβείας πόθον, πολλὰ χαίρειν φράσαντες ταῖς ἄλλαις πραγματείαις ὅλον ἀνέθεσαν τὸν οἰκεῖον βίον θεραπείᾳ θεοῦ.", "st": "108"}, {"sp": "N", "t": "οἱ δ’ οὐδὲν ἔξω τῶν πρὸς ἀνθρώπους δικαιωμάτων ἀγαθὸν ὑποτοπήσαντες εἶναι μόνην τὴν πρὸς ἀνθρώπους ὁμιλίαν ἠσπάσαντο, τῶν τε ἀγαθῶν τὴν χρῆσιν ἐξ ἴσου πᾶσι παρέχοντες διὰ κοινωνίας ἵμερον καὶ τὰ δεινὰ κατὰ δύναμιν ἐπικουφίζειν ἀξιοῦντες.", "st": "109"}, {"sp": "N", "t": "τούτους μὲν οὖν φιλανθρώπους, τοὺς δὲ προτέρους φιλοθέους ἐνδίκως ἂν εἴποι τις, ἡμιτελεῖς τὴν ἀρετήν· ὁλόκληροι γὰρ οἱ παρ’ ἀμφοτέροις εὐδοκιμοῦντες. ὅσοι δὲ μήτ’ ἐν τοῖς πρὸς ἀνθρώπους ἐξετάζονται, συνηδόμενοι μὲν ἐπὶ τοῖς κοινοῖς ἀγαθοῖς, συναλγοῦντες δ’ ἐπὶ τοῖς ἐναντίοις, μήτ’ εὐσεβείας καὶ ὁσιότητος περιέχονται, μεταβεβληκέναι δόξαιεν ἂν εἰς θηρίων φύσιν· ὧν τῆς ἀγριότητος οἴσονται τὰ πρωτεῖα οἱ γονέων ἀλογοῦντες, ἑκατέρας μερίδος ὄντες ἐχθροὶ καὶ τῆς", "st": "110"}, {"sp": "N", "t": "πρὸς θεὸν καὶ τῆς πρὸς ἀνθρώπους. ἐν δυσὶν οὖν δικαστηρίοις, ἃ δὴ μόνα ἐστὶν ἐν τῇ φύσει, μὴ ἀγνοείτωσαν ἑαλωκότες, ἀσεβείας μὲν ἐν τῷ θείῳ, διότι τοὺς ἐκ τοῦ μὴ ὄντος εἰς τὸ εἶναι παραγαγόντας καὶ κατὰ τοῦτο μιμησαμένους θεὸν οὐ περιέπουσι, μισανθρωπίας δ’ ἐν τῷ κατ’ ἀνθρώπους.", "st": "111"}, {"sp": "N", "t": "τίνα γὰρ ἕτερον εὖ ποιήσουσιν οἱ τῶν συγγενεστάτων καὶ τὰς μεγίστας παρασχομένων δωρεὰς ὀλιγωροῦντες, ὧν ἔνιαι δι’ ὑπερβολὴν οὐδ’ ἀμοιβὰς ἐνδέχονται; πῶς γὰρ ἂν ὁ γεννηθεὶς ἀντιγεννῆσαι δύναιτο τοὺς σπείραντας, κλῆρον ἐξαίρετον τῆς φύσεως χαρισαμένης πρὸς παῖδας γονεῦσιν εἰς ἀντίδοσιν ἐλθεῖν οὐ δυνάμενον; ὅθεν καὶ σφόδρα προσῆκεν ἀγανακτεῖν, εἰ μὴ πάντα ἔχοντες ἀντιχαρίζεσθαι μηδὲ τὰ κουφότατα ἐθελήσουσιν.", "st": "112"}, {"sp": "N", "t": "οἷς δεόντως ἂν εἴποιμι· τὰ θηρία πρὸς ἀνθρώπους ἡμεροῦσθαι δεῖ· καὶ πολλάκις ἔγνων ἡμερωθέντας λέοντας, ἄρκτους, παρδάλεις, οὐ μόνον πρὸς τοὺς τρέφοντας διὰ τὴν ἐπὶ τοῖς ἀναγκαίοις χάριν, ἀλλὰ καὶ πρὸς τοὺς ἄλλους, ἕνεκά μοι δοκῶ τῆς πρὸς ἐκείνους ὁμοιότητος· καλὸν γὰρ ἀεὶ τῷ κρείττονι τὸ χεῖρον ἀκολουθεῖν διὰ βελτιώσεως ἐλπίδα.", "st": "113"}, {"sp": "N", "t": "νυνὶ δ’ ἀναγκασθήσομαι τἀναντία λέγειν· μιμηταὶ θηρίων ἐνίων, ἄνθρωποι, γίνεσθε. τοὺς ὠφεληκότας ἀντωφελεῖν ἐκεῖνα οἶδε καὶ πεπαίδευται· κύνες οἰκουροὶ προασπίζουσι καὶ προαποθνῄσκουσι τῶν δεσποτῶν, ὅταν κίνδυνός τις ἐξαπιναίως καταλάβῃ· τοὺς δ’ ἐν ταῖς ποίμναις φασὶ προαγωνιζομένους τῶν θρεμμάτων ἄχρι νίκης ἢ θανάτου παραμένειν ὑπὲρ τοῦ διατηρῆσαι τοὺς ἀγελάρχας ἀζημίους.", "st": "114"}, {"sp": "N", "t": "εἶτ’ οὐκ αἰσχρῶν ἐστιν αἴσχιστον, ἐν χαρίτων ἀμοιβαῖς ἄνθρωπον ἡττηθῆναι κυνός, τοῦ θηρίων θρασυτάτου τὸ ἡμερώτατον ζῷον; ἀλλ’ εἰ μὴ τοῖς χερσαίοις ἀναδιδασκόμεθα, πρὸς τὴν πτηνὴν καὶ ἀεροπόρον μετίωμεν φύσιν ἃ χρὴ παρ’ αὐτῆς μαθησόμενοι.", "st": "115"}, {"sp": "N", "t": "τῶν πελαργῶν οἱ μὲν γηραιοὶ καταμένουσιν ἐν ταῖς νεοττιαῖς ἀδυνατοῦντες ἵπτασθαι οἱ δὲ τούτων παῖδες ὀλίγου δέω φάναι γῆν καὶ θάλατταν ἐπιποτώμενοι πανταχόθεν ἐκπορίζουσι τοῖς γονεῦσι τὰ ἐπιτήδεια·", "st": "116"}, {"sp": "N", "t": "καὶ οἱ μὲν ἀξίω τῆς ἡλικίας ἠρεμοῦντες ἐν ἀφθονίᾳ διατελοῦσι τῇ πάσῃ τρυφῶντες, οἱ δὲ τὰς εἰς τὸν πορισμὸν κακοπαθείας ἐπελαφριζόμενοι τῷ εὐσεβεῖν καὶ τῷ προσδοκᾶν ἐν γήρᾳ τὰ αὐτὰ πείσεσθαι ὑπὸ τῶν ἐκγόνων ἀναγκαῖον ὄφλημα ἀντεκτίνουσιν, ἐν καιρῷ καὶ λαβόντες αὐτὸ καὶ ἀνταποδιδόντες, ὅτ’ οὐδέτεροι τρέφειν αὑτοὺς δύνανται, παῖδες μὲν ἐν ἀρχῇ τῆς γενέσεως, γονεῖς δ’ ἐπὶ τελευτῇ τοῦ βίου· ὅθεν αὐτοδιδάκτῳ τῇ φύσει νεοττοτροφηθέντες γηροτροφοῦσι χαίροντες.", "st": "117"}, {"sp": "N", "t": "ἆρ’ οὐκ ἄξιον ἐπὶ τούτοις ἀνθρώπους, ὅσοι γονέων ἀμελοῦσιν, ἐγκαλύπτεσθαι καὶ κακίζειν ἑαυτούς, ὠλιγωρηκότας ὧν ἢ μόνων ἢ πρὸ τῶν ἄλλωι ἀναγκαῖον ἦν πεφροντικέναι, καὶ ταῦτ’ οὐ διδόντας μᾶλλον ἢ ἀποδιδόντας; παίδων γὰρ ἴδιον οὐδέν, ὃ μὴ γονέων ἐστίν, ἢ οἴκοθεν ἐπιδεδωκότων ἢ τὰς αἰτίας ἰῆς κτήσεως παρασχομένων.", "st": "118"}, {"sp": "N", "t": "εὐσέβειαν δὲ καὶ ὁσιότητα, τὰς ἀρετῶν ἡγεμονίδας, ἆρά γ’ ἐντὸς ὅρων ἔχουσι τῶν ψυχῶν; ὑπερορίους μὲν οὖν ἀπεληλάκασι καὶ πεφυγαδεύκασι· θεοῦ γὰρ ὑπηρέται πρὸς τέκνων σπορὰν οἱ γονεῖς· ὁ δ’ ὑπηρέτην ἀτιμάζων συνατιμάζει καὶ τὸν ἄρχοντα.", "st": "119"}, {"sp": "N", "t": "τῶν δ’ εὐτολμοτέρων ἀποσεμνύνοντες τὸ γονέων ὄνομά φασί τινες, ὡς ἄρα πατὴρ καὶ μήτηρ ἐμφανεῖς εἰσι θεοί, μιμούμενοι τὸν ἀγένητον ἐν τῷ ζῳοπλαστεῖν· ἀλλὰ τὸν μὲν εἶναι τοῦ κόσμου θεόν, τοὺς δὲ μόνων ὧν ἐγέννησαν. ἀμήχανον δ’ εὐσεβεῖσθαι τὸν ἀόρατον ὑπὸ τῶν εἰς τοὺς ἐμφανεῖς καὶ ἐγγὺς ὄντας ἀσεβούντων.", "st": "120"}, {"sp": "N", "t": "Τοσαῦτα καὶ περὶ γονέων τιμῆς φιλοσοφήσας τέλος ἐπιτίθησι τῇ ἑτέρᾳ καὶ θειοτέρᾳ πεντάδι. τὴν δ’ ἑτέραν ἀναγραψάμενος περιέχουσαν ἀπαγορεύσεις τῶν πρὸς ἀνθρώπους ἀπὸ μοιχείας ἄρχεται, μέγιστον ἀδικημάτων τοῦτ’ εἶναι ὑπολαβών.", "st": "121"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ πηγὴν ἔχει φιληδονίαν, ἣ καὶ τὰ σώματα θρύπτει τῶν ἐχόντων καὶ τοὺς τῆς ψυχῆς ἐκλύει τόνους καὶ τὰς οὐσίας διαφθείρει πάντα δίκην ἀσβέστου πυρὸς ὧν ἄν προσάψηται καταφλέγουσα καὶ μηδὲν σῷον ἀπολείπουσα τῶν κατὰ τὸν ἀνθρώπινον βίον.", "st": "122"}, {"sp": "N", "t": "ἔπειτ’ ἀναπείθει τὸν μοιχὸν οὐκ ἀδικεῖν μόνον ἀλλὰ καὶ διδάσκειν συναδικεῖν ἐν ἀκοινωνήτοις πράγμασι κοινωνίαν τιθέμενον· οἴστρου γὰρ τοῦ κατασχόντος, ἀμήχανον λαβεῖν τέλος δι’ ἑνὸς μόνου τὰς ὀρέξεις, ἀλλὰ δεῖ πάντως δύο κοινοπραγῆσαι, τὸν μὲν ὑφηγητοῦ τὸν δὲ γνωρίμου τάξιν λαβόντα, πρὸς ἀκρασίας καὶ λαγνείας βεβαίωσιν, αἰσχίστων κακῶν.", "st": "123"}, {"sp": "N", "t": "οὐδὲ γὰρ τοῦτ’ ἔνεστιν εἰπεῖν, ὡς τὸ σῶμα μόνον διαφθείρεται τῆς μοιχευομένης γυναικός, ἀλλ’, εἰ δεῖ τἀληθὲς εἰπεῖν, ἡ ψυχὴ πρὸ τοῦ σώματος εἰς ἀλλοτρίωσιν ἐθίζεται διδασκομένη πάντα τρόπον ἀποστρέφεσθαι καὶ μισεῖν τὸν ἄνδρα.", "st": "124"}, {"sp": "N", "t": "καὶ ἧττον ἂν ἦν δεινόν, εἰ τὸ μῖσος ἐπεδείκνυτο ἐμφανές — τὰ γὰρ ἐν περιόπτῳ ῥᾷον φυλάξασθαι —· νυνὶ δὲ δυσυπονόητον καὶ δυσθήρατόν ἐστι, πανούργοις τέχναις συσκιαζόμενον καὶ τὴν ἐναντίαν ἔστιν ὅτε τοῦ φιλεῖν δόξαν ἐμποιοῦν γοητείαις τισὶ καὶ ἀπάταις.", "st": "125"}, {"sp": "N", "t": "ἀναστάτους γε μὴν τρεῖς ἀποδεικνύουσιν οἴκους, τόν τε τοῦ παρασπονδουμένου ἀνδρός, ὃς τὰς ἐπὶ γάμοις εὐχὰς καὶ τὰς ἐπὶ γνησίοις παισὶν ἐλπίδας περικόπτεται, καὶ δύο δ’ ἑτέρους τόν τε τοῦ μοιχοῦ καὶ τὸν τῆς γυναικός· καὶ γὰρ τούτων ἑκάτερος ὕβρεως καὶ ἀτιμίας καὶ τῶν μεγίστων ὀνειδῶν ἀναπίμπλαται.", "st": "126"}, {"sp": "N", "t": "κἄν πολυάνθρωποι μὲν τύχωσιν αἱ συγγένειαι διὰ τὰς ἐπιγαμίας καὶ τὰς ἄλλων πρὸς ἄλλους ἐπιμιξίας, ἅψεται καὶ τῆς πόλεως ἁπάσης ἐν κύκλῳ βαδίζον τἀδίκημα.", "st": "127"}, {"sp": "N", "t": "παγχάλεπόν γε μὴν καὶ ὁ τῶν τέκνων ἐπαμφοτερισμός· μὴ γὰρ ἁγνευούσης γυναικός, ἀμφίδοξον καὶ ἄδηλον, τὰ ἀποκυόμενα τίνος ἐστὶ τῇ ἀληθείᾳ πατρός· εἶτα λανθάνοντος τοῦ πράγματος, οἱ μοιχίδιοι τὴν τῶν γνησίων παρασπασάμενοι τάξιν ἀλλοτρίαν γενεὰν νοθεύουσι καὶ κλῆρον ὅσον τῷ δοκεῖν πατρῷον οὐδὲν προσήκοντα διαδέξονται.", "st": "128"}, {"sp": "N", "t": "καὶ ὁ μὲν μοιχὸς ἐφυβρίσας καὶ ἐναπερυγὼν τὸ πάθος, ἐπίληπτον σπορὰν σπείρας, ὅταν ἀποπλησθῇ τῆς ἐπιθυμίας, οἰχήσεται καταλιπών, γέλωτα θέμενος τὴν τοῦ παρανομηθέντος ἄγνοιαν· ὁ δ’ οἷα τυφλὸς μηδὲν τῶν ὑποικουρημένων ἐπιστάμενος ὡς οἰκειότατα ἔκγονα τὰ ἐκ τῶν πολεμιωτάτων θεραπεύειν ἀναγκασθήσεται.", "st": "129"}, {"sp": "N", "t": "φανερὸν δ’ εἰ γένοιτο τἀδίκημα, κακοδαιμονέστατοι γένοιντ’ ἂν οἱ μηδὲν ἠδικηκότες ἄθλιοι παῖδες, μηδετέρῳ γένει προσνεθῆναι δυνάμενοι, μήτε τῷ τοῦ γήμαντος μήτε τῷ τοῦ μοιχοῦ.", "st": "130"}, {"sp": "N", "t": "τοιαύτας συμφορὰς ἀπεργαζομένης τῆς ἐκνόμου μίξεως, εἰκότως στυγητὸν καὶ θεομίσητον πρᾶγμα, μοιχεία, πρῶτον ἀδικημάτων ἀνεγράφη.", "st": "131"}, {"sp": "N", "t": "Δεύτερον δὲ πρόσταγμα μὴ ἀνδροφονεῖν. ἀγελαστικὸν γὰρ καὶ σύννομον ζῷον τὸ ἡμερώτατον ἄνθρωπον ἡ φύσις γεννήσασα πρὸς ὁμόνοιαν καὶ κοινωνίαν ἐκάλεσε. λόγον δοῦσα συναγωγὸν εἰς ἁρμονίαν καὶ κρᾶσιν ἠθῶν. ὁ δὴ κτείνων τινὰ μὴ ἀγνοείτω νόμους φύσεως καὶ θεσμοὺς ἀνατρέπων καλῶς καὶ συμφερόντως ἅπασι γραφέντας.", "st": "132"}, {"sp": "N", "t": "ἴστω μέντοι καὶ ἱεροσυλίας ἔνοχος ὢν τὸ ἱερώτατον τῶν τοῦ θεοῦ κτημάτων σεσυληκώς· τί γὰρ σεμνότερον ἢ ἁγιώτερον ἀνάθημα ἀνθρώπου; χρυσὸς μὲν καὶ ἄργυρος καὶ λίθοι πολυτελεῖς καὶ ὅσαι ἄλλαι τιμαλφέσταται ὗλαι κόσμος οἰκοδομημάτων ἐστίν, ἄψυχος ἀψύχων·", "st": "133"}, {"sp": "N", "t": "ἄνθρωπος δέ, ζῷον ἄριστον κατὰ τὸ κρεῖττον τῶν ἐν αὐτῷ, τὴν ψυχήν, συγγενέστατος τῷ καθαρωτάτῳ τῆς οὐσίας οὐρανῷ, ὡς δ’ ὁ τῶν πλείστων λόγος, καὶ τῷ τοῦ κόσμου πατρί, τῶν ἐπὶ γῆς ἁπάντων οἰκειότατον ἀπεικόνισμα καὶ μίμημα τῆς ἀιδίου καὶ εὐδαίμονος ἰδέας τὸν νοῦν λαβών.", "st": "134"}, {"sp": "N", "t": "τρίτον δ’ ἐστὶ τῆς δευτέρας πεντάδος παράγγελμα μὴ κλέπτειν. ὁ γὰρ τοῖς ἀλλοτρίοις ἐπικεχηνὼς κοινὸς πόλεως ἐχθρός, βουλήσει μὲν τὰ πάντων δυνάμει δὲ τά τινων ὑφαιρούμενος, τῷ τὴν μὲν πλεονεξίαν ἐπὶ μήκιστον ἐκτείνεσθαι, τὸ δ’ ἀσθενὲς ὑστερίζον εἰς βραχὺ στέλλεσθαι καὶ μόνον φθάνειν ἐπ’ ὀλίγους.", "st": "135"}, {"sp": "N", "t": "ὅσοι τοίνυν τῶν κλεπτῶν ἰσχὺν προσέλαβον, ὅλας συλῶσι πόλεις ἀλογοῦντες τιμωριῶν διὰ τὸ ἐπικυδέστεροι τῶν νόμων εἶναι δοκεῖν· οὗτοι δ’ εἰσὶν οἱ ὀλιγαρχικοὶ τὰς φύσεις, οἱ τυραννίδων καὶ δυναστειῶν ἐπιθυμοῦντες, οἱ τὰς μεγάλας ἐργαζόμενοι κλοπάς, σεμνοῖς ὀνόμασι τοῖς ἀρχῆς καὶ ἡγεμονίας ἐπικρύπτοντες λῃστείαν τἀληθὲς ἔργον.", "st": "136"}, {"sp": "N", "t": "ἐκ πρώτης οὖν ἡλικίας ἀναδιδασκέσθω τις μηδὲν λάθρα τῶν ἀλλοτρίων ὑφαιρεῖσθαι, κἄν βραχύτατον ᾖ, διότι ἐγχρονίζον ἔθος φύσεως κραταιότερόν ἐστι καὶ τὰ μικρὰ μὴ κωλυόμενα φύεται καὶ ἐπιδίδωσι πρὸς μέγεθος συναυξανόμενα.", "st": "137"}, {"sp": "N", "t": "Κλέπτειν δ’ ἀπειπὼν ἑξῆς ψευδομαρτυρεῖν ἀπαγορεύει, πολλοῖς καὶ μεγάλοις καὶ πᾶσι χαλεποῖς τοὺς ψευδομάρτυρας ἐνόχους εἰδώς. τὸ μὲν γὰρ πρῶτον φθείρουσι τὴν σεμνὴν ἀλήθειαν, ἧς οὐκ ἔστιν ἐν βίῳ κτῆμα ἱερώτερον, ἡλίου τρόπον φῶς τοῖς πράγμασι περιτιθείσης, ἵνα μηδὲν αὐτῶν ἐπισκιάζηται.", "st": "138"}, {"sp": "N", "t": "δεύτερον δὲ πρὸς τῷ ψεύδεσθαι καὶ τὰ πράγματα οἷα νυκτὶ καὶ σκότῳ βαθεῖ περιαμπίσχουσι καὶ συμπράττουσι μὲν τοῖς ἁμαρτάνουσιν, ἐπιτίθενται δὲ τοῖς ἀδικουμένοις, ἃ μήτ’ εἶδον μήτ’ ἤκουσαν μήτ’ ἴσασι παγίως εἰδέναι καὶ σφόδρα κατειληφέναι διαβεβαιούμενοι.", "st": "139"}, {"sp": "N", "t": "προσεξεργάζονται δὲ καὶ τρίτον παρανόμημα τῶν προτέρων ἀργαλεώτερον· ὅταν γὰρ σπάνις ἀποδείξεων ᾖ διὰ λόγων ἢ διὰ γραμμάτων, ἐπὶ μάρτυρας καταφεύγουσιν οἱ τὰς ἀμφισβητήσεις ἔχοντες, ὧν τὰ ῥήματα κανόνες εἰσὶ τοῖς δικασταῖς περὶ ὧν μέλλουσιν ἀποφαίνεσθαι· μόνοις γὰρ τούτοις ἐπανέχειν ἀνάγκη, μηδενὸς ὄντος ἑτέρου τῶν εἰς ἔλεγχον· ἐξ οὗ συμβαίνει, τοὺς μὲν καταμαρτυρουμένους ἀδικεῖσθαι νικᾶν δυναμένους, τοὺς δὲ προσέχοντας δικαστὰς ἀδίκους καὶ παρανόμους ψήφους ἀντὶ νομίμων καὶ δικαίων γράφειν.", "st": "140"}, {"sp": "N", "t": "τὸ μέντοι πανούργημα φθάνει καὶ πρὸς ἀσέβειαν· οὐ γὰρ ἀνωμότοις δικάζειν ἔθος, ἀλλὰ μετὰ φρικωδεστάτων ὅρκων, οὓς παραβαίνουσι πρὸ τῶν ἀπατωμένων οἱ φενακίζοντες, ἐπειδὴ τῶν μὲν τὸ σφάλμα οὐ κατὰ γνώμην, οἱ δ’ ἐπιστήμῃ καταστρατηγοῦσι καὶ ἐκ προνοίας ἁμαρτάνοντες καὶ τοὺς κυρίους τῆς ψήφου συνεξαμαρτάνειν ἀναπείθοντες οὐκ εἰδότας ὃ δρῶσιν ἐπὶ τιμωρίᾳ τῶν οὐδεμιᾶς ἀξίων κολάσεως. διὰ μὲν δὴ ταῦτά μοι δοκεῖ ψευδομαρτυρίαν ἀπειπεῖν.", "st": "141"}, {"sp": "N", "t": "τελευταῖον δ’ ἐπιθυμεῖν ἀπαγορεύει νεωτεροποιὸν καὶ ἐπίβουλον τὴν ἐπιθυμίαν εἰδώς. πάντα μὲν γὰρ τὰ ψυχῆς πάθη χαλεπά, κινοῦντα καὶ σείοντα αὐτὴν παρὰ φύσιν καὶ ὑγιαίνειν οὐκ ἐῶντα, χαλεπώτατον δ’ ἐπιθυμία· διὸ τῶν μὲν ἄλλων ἕκαστον θύραθεν ἐπεισιὸν καὶ προσπῖπτον ἔξωθεν ἀκούσιον εἶναι δοκεῖ, μόνη δ’ ἐπιθυμία τὴν ἀρχὴν ἐξ ἡμῶν αὐτῶν λαμβάνει καὶ ἔστιν ἑκούσιος.", "st": "142"}, {"sp": "N", "t": "τί δ’ ἐστὶν ὃ λέγω; τοῦ παρόντος καὶ νομισθέντος ἀγαθοῦ φαντασία διεγείρει καὶ διανίστησι τὴν ψυχὴν ἠρεμοῦσαν καὶ σφόδρα μετέωρον ἐξαίρει καθάπερ ὀφθαλμοὺς φῶς ἀναστράψαν· καλεῖται δὲ τουτὶ τὸ πάθος αὐτῆς ἡδονή.", "st": "143"}, {"sp": "N", "t": "τὸ δ’ ἐναντίον ἀγαθῷ κακόν, ὅταν ἐκβιασάμενον πληγὴν ἐπενέγκῃ καίριον, συννοίας καὶ κατηφείας εὐθὺς αὐτὴν ἀναπίμπλησιν ἄκουσαν·", "st": "144"}, {"sp": "N", "t": "ὄνομα δὲ καὶ τούτῳ τῷ πάθει λύπη. ὅταν δὲ τὸ κακὸν μήπω μὲν εἰσῳκισμένον θλίβῃ, μέλλῃ δ’ ἀφικνεῖσθαι καὶ παρευτρεπίζηται, πτοίαν καὶ ἀγωνίαν, ἀποφράδας ἀγγέλους, προεκπέμπει δειματοῦντας· φόβος δὲ προσαγορεύεται τὸ πάθος.", "st": "145"}, {"sp": "N", "t": "ἐπειδὰν δὲ λαβών τις ἔννοιαν ἀγαθοῦ μὴ παρόντος ὀρέγηται τυχεῖν αὐτοῦ, πρὸς μήκιστον τὴν ψυχὴν ἐλαύνων καὶ ἐπὶ πλεῖστον ἐκτείνων, ψαῦσαι τοῦ ποθουμένου γλιχόμενος, ὥσπερ ἐπὶ τροχοῦ κατατείνεται, σπεύδων μὲν συλλαβεῖν, ἐφικνεῖσθαι δ’ ἀδυνατῶν καὶ ταὐτὸν πεπονθὼς τοῖς τοὺς ἐξαναχωροῦντα διώκουσιν ἐλάττονι μὲν τάχει προθυμίᾳ δ’ ἀνανταγωνίστῳ.", "st": "146"}, {"sp": "N", "t": "ὅμοιον δέ τι καὶ περὶ τὰς αἰσθήσεις ἔοικε συμβαίνειν· ὀφθαλμοί τε γὰρ πολλάκις ὁρατοῦ τινος πάνυ μακρὰν ἀφεστῶτος εἰς κατάληψιν ἐλθεῖν ἐπειγόμενοι τείνοντες αὑτούς, εὖ μάλα καὶ πλέον τῆς δυνάμεως ἐνεχθέντες, ὤλισθον κατὰ κενοῦ περὶ τὴν ἀκριβῆ τοῦ ὑποκειμένου γνῶσιν σφαλέντες καὶ προσέτι τὴν ὄψιν τῷ βιαίῳ καὶ συντόνῳ τῆς ἀτενοῦς προσβολῆς ἀσθενήσαντες ἀμαυροῦνται.", "st": "147"}, {"sp": "N", "t": "καὶ θροῦ πάλιν ἀσαφοῦς ἐκ μακροῦ διαστήματος φερομένου, τὰ ὦτα ἀνεγερθέντα καὶ ἐπουρίσαντα ἵεται καὶ σπεύδει προσελθεῖν εἰ οἷόν τε ἐγγυτέρω, πόθῳ τοῦ τρανωθῆναι ταῖς ἀκοαῖς τὸν ἦχον· ὁ δ’ —", "st": "148"}, {"sp": "N", "t": "ἔτι γὰρ ἀμαυρὸς ὡς ἔοικε προσπίπτει — οὐδὲν τῶν εἰς γνῶσιν τηλαυγέστερον ἐπιδίδωσιν, ὡς ἔτι μᾶλλον τὸν ἀνήνυτον καὶ ἀδιεξίτητον ἐπιτείνεσθαι τοῦ καταλαβεῖν ἵμερον, Ταντάλειον τιμωρίαν ἐπιφερούσης τῆς ἐπιθυμίας· ἐκεῖνός τε γὰρ ὧν ὀρεχθείη πάντων ὁπότε μέλλοι ψαύσειν, ἀπετύγχανεν, ὅ τε κρατηθεὶς ἐπιθυμίᾳ, διψῶν ἀεὶ τῶν ἀπόντων, οὐδέποτε πληροῦται περὶ κενὴν ἰλυσπώμενος τὴν ὄρεξιν.", "st": "149"}, {"sp": "N", "t": "ὥσπερ τε τὰ ἑρπηνώδη τῶν νοσημάτων, εἰ μὴ προανακρουσθείη τομαῖς ἢ καύσεσιν, ἐπιθέοντα σύμπασαν ἐν κύκλῳ καταλαμβάνει τὴν τοῦ σώματος κοινωνίαν οὐδὲν ἀπαθὲς μέρος ἐῶντα, οὕτως, εἰ μὴ λόγος ὁ κατὰ φιλοσοφίαν ἰατροῦ δίκην ἀγαθοῦ ῥέουσαν τὴν ἐπιθυμίαν ἐπίσχοι, πάντ’ ἐξ ἀνάγκης τὰ τοῦ βίου πράγματα κινηθήσεται παρὰ φύσιν· οὐδὲν γάρ ἐστιν ὑπεξῃρημένον ὃ διαφεύγει τὸ πάθος, ἀλλ’ ὅταν ἄδειαν λάβῃ καὶ ἐκεχειρίαν, ἐπινέμεται καὶ σίνεται πάντα διὰ πάντων.", "st": "150"}, {"sp": "N", "t": "εὔηθες ἴσως μακρηγορεῖν ἐστι περὶ τῶν οὕτως ἐμφανῶν, ἃ τίς ἀνὴρ ἢ πόλις ἀγνοεῖ καθ’ ἑκάστην οὐχ ἡμέραν μόνον ἀλλὰ καὶ ὥραν ὡς ἔπος εἰπεῖν ἔλεγχον ἐναργῆ παριστάντα; χρημάτων ἔρως ἢ γυναικὸς ἢ δόξης ἤ τινος ἄλλου τῶν ἡδονὴν ἀπεργαζομένων ἆρά γε μικρῶν καὶ τῶν τυχόντων αἴτιος γίνεται κακῶν;", "st": "151"}, {"sp": "N", "t": "οὐ διὰ τοῦτον συγγένειαι μὲν ἀλλοτριοῦνται τὴν φυσικὴν εὔνοιαν μεθαρμοζόμεναι πρὸς ἀνήκεστον ἔχθραν, χῶραι δὲ μεγάλαι καὶ πολυάνθρωποι στάσεσιν ἐμφυλίοις ἐρημοῦνται, γῆ δὲ καὶ θάλαττα πληροῦται τῶν καινουργουμένων αἰεὶ συμφορῶν ναυμαχίαις καὶ πεζαῖς στρατιαῖς;", "st": "152"}, {"sp": "N", "t": "οἱ γὰρ Ἑλλήνων καὶ βαρβάρων πρός τε ἑαυτοὺς καὶ πρὸς ἀλλήλους τραγῳδηθέντες πόλεμοι πάντες ἀπὸ μιᾶς πηγῆς ἐρρύησαν, ἐπιθυμίας ἢ χρημάτων ἢ δόξης ἢ ἡδονῆς· περὶ γὰρ ταῦτα κηραίνει τὸ τῶν ἀνθρώπων γένος.", "st": "153"}, {"sp": "N", "t": "Ἅλις μὲν δὴ τούτων. χρὴ δὲ μηδ’ ἐκεῖνο ἀγνοεῖν, ὅτι οἱ δέκα λόγοι κεφάλαια νόμων εἰσὶ τῶν ἐν εἴδει παρ’ ὅλην τὴν νομοθεσίαν ἐν ταῖς ἱεραῖς βίβλοις ἀναγραφέντων.", "st": "154"}, {"sp": "N", "t": "ὁ μὲν πρῶτος τῶν περὶ μοναρχίας· οὗτοι δὲ δηλοῦσιν, ὅτι ἓν αἴτιον τοῦ κόσμου καὶ ἡγεμὼν καὶ βασιλεὺς εἷς ὁ ἡνιοχῶν καὶ κυβερνῶν τὰ ὅλα σωτηρίως, ὀλιγαρχίαν ἢ ὀχλοκρατίαν, ἐπιβούλους πολιτείας φυομένας παρ’ ἀνθρώποις τοῖς κακίστοις ἐξ ἀταξίας καὶ πλεονεξίας, ἐξεληλακὼς ἐκ τοῦ καθαρωτάτου τῆς οὐσίας, οὐρανοῦ.", "st": "155"}, {"sp": "N", "t": "ὁ δὲ δεύτερος κεφάλαιόν ἐστι πάντων, ὅσα περὶ χειροκμήτων ἐνομοθετεῖτο, ἀγάλματα καὶ ξόανα καὶ συνόλως ἀφιδρύματα, ὧν γραφικὴ καὶ πλαστικὴ βλαβεραὶ δημιουργοί, κατασκευάζειν οὐκ ἐῶν οὐδ’ ὅσα μύθων πλάσματα προσίεσθαι, θεογαμίαν καὶ θεογονίαν καὶ τὰς ἀμφοτέραις ἑπομένας ἀμυθήτους καὶ ἀργαλεωτάτας κῆρας.", "st": "156"}, {"sp": "N", "t": "τῷ δὲ τρίτῳ ὑποστέλλει τά τε ἀνώμοτα πάντα καὶ ἐφ’ οἷς ὀμνύναι δεῖ καὶ ὁπότε καὶ ὅπου χρὴ καὶ τίνα καὶ πῶς ἔχοντα κατά τε ψυχὴν καὶ σῶμα καὶ ὅσα ἐπ’ εὐόρκοις καὶ τοὐναντίον ἐχρήσθη.", "st": "157"}, {"sp": "N", "t": "τὸ δὲ τέταρτον, τὸ περὶ τῆς ἑβδομάδος, οὐδὲν ἀλλ’ ἢ κεφάλαιον νομιστέον ἑορτῶν καὶ τῶν διατεταγμένων εἰς ἑκάστην ἁγνευτικῶν, περιρραντηρίων τε αἰσίων καὶ ἐπηκόων εὐχῶν καὶ θυσιῶν τελείων, αἷς ἡ λατρεία ἐγίνετο.", "st": "158"}, {"sp": "N", "t": "ἑβδόμην δὲ λέγω καὶ τὴν σὺν ἑξάδι τῇ γονιμωτάτῃ καὶ τὴν ἄνευ ἑξάδος, ἐπιπροσθοῦσαν αὐτῇ, μονάδι ὁμοιουμένην, ὧν ἑκατέρᾳ τὰς ἑορτὰς παραριθμεῖ· μονάδι μὲν τήν τε ἱερομηνίαν, ἣν σάλπιγξιν ὑποσημαίνουσι, καὶ νηστείαν, ἐν ᾗ σιτίων καὶ ποτῶν ἀποχὴ διείρηται, καὶ ἣν Ἑβραῖοι πατρίῳ γλώττῃ Πάσχα προσαγορεύουσιν, ἐν ᾗ θύουσι πανδημεὶ αὐτῶν ἕκαστος τοὺς ἱερεῖς αὐτῶν οὐκ ἀναμένοντες, ἱερωσύνην τοῦ νόμου χαρισαμένου τῷ ἔθνει παντὶ κατὰ μίαν ἡμέραν ἐξαίρετον ἀνὰ πᾶν ἔτος εἰς αὐτουργίαν θυσιῶν·", "st": "159"}, {"sp": "N", "t": "καὶ ἔτι τὴν ἐν ᾗ προσφέρεται δράγμα χαριστήριον εὐγονίας καὶ φορᾶς τῆς πεδιάδος δι’ ἀσταχύων πληρώσεως· καὶ τὴν ἀπὸ ταύτης καταριθμουμένην ἑπτὰ ἑβδομάσι πεντηκοστὴν ἡμέραν, ἐν ᾗ προσάγειν ἄρτους ἔθος, οἳ καλοῦνται πρωτογεννημάτων ἐτύμως, ἐπειδήπερ εἰσὶν ἀπαρχὴ γεννημάτων καὶ καρπῶν ἡμέρου τροφῆς, ἣν ἀνθρώπῳ τῷ ἡμερωτάτῳ ζῴων ἀπένειμεν ὁ θεός.", "st": "160"}, {"sp": "N", "t": "ἑβδομάδι δὲ τὰς μεγίστας καὶ πολυημέρους ἑορτὰς προσένειμε κατὰ τὰς τοῦ ἔτους ἰσημηρίας, ἐαρινὴν καὶ μετοπωρινήν, δύο δυσὶν ἀναθείς, ἑκατέραν ἐφ’ ἡμέρας ἑπτά, τὴν μὲν κατὰ τὸ ἔαρ ἐπὶ τελειώσει τῶν σπειρομένων, τὴν δὲ μετοπωρινὴν ἐπὶ συγκομιδῇ καρπῶν ἁπάντων, οὓς καὶ τὰ δένδρα ἤνεγκεν· ἑπτὰ δ’ ἡμέραι ἀπενεμήθησαν εἰκότως ἑπτὰ μησὶ τῆς ἰσημερίας ἑκατέρας, ἵνα μὴν ἕκαστος λαμβάνῃ γέρας ἐξαίρετον μίαν ἱερὰν ἡμέραν ἑορτώδη πρὸς εὐθυμίαν καὶ ἀπόλαυσιν ἐκεχειρίας.", "st": "161"}, {"sp": "N", "t": "ἐμφέρονται δὲ καὶ ἄλλοι νόμοι πάνυ καλῶς τεθέντες, εἰς ἡμερότητα καὶ κοινωνίαν ἀτυφίαν τε καὶ ἰσότητα προκαλούμενοι· τούτων οἱ μέν εἰσι περὶ τοῦ λεγομένου ἑβδοματικοῦ, καθ’ ὃ διείρηται πᾶσαι ἀργὴν τὴν χώραν ἐᾶν μήτε σπείροντας μήτε ἀροῦντας μήτε δένδρα διακαθαίροντας ἢ τέμνοντας ἢ ὅσ’ ἄλλα τῶν κατὰ γεωργίαν ἐπιτελοῦντας·", "st": "162"}, {"sp": "N", "t": "ἓξ γὰρ ἐνιαυτοῖς τήν τε πεδιάδα καὶ τὴν ὀρεινὴν εἰς καρπῶν γένεσιν καὶ δασμῶν ἐτήσιον φορὰν πονηθείσας ἀνέσεως ἠξίωσε τοῦ διαπνεῦσαι χάριν καὶ ἀπελευθεριάσαι χρησαμένας ἀνεπικελεύστῳ τῇ φύσει.", "st": "163"}, {"sp": "N", "t": "ἕτεροι δ’ εἰσὶ περὶ τοῦ πεντηκοστοῦ ἔτους, ἐν ᾧ τά τε λεχθέντα ἀρτίως ἐπιτελεῖται καὶ — τὸ ἀναγκαιότατον — τῶν κληρουχιῶν ἀποκατάστασις εἰς τοὺς ἐξ ἀρχῆς λαχόντας οἴκους, πρᾶγμα φιλανθρωπίας καὶ δικαιοσύνης μεστόν.", "st": "164"}, {"sp": "N", "t": "τὸ δὲ πέμπτον, τὸ περὶ γονέων τιμῆς, πολλοὺς καὶ ἀναγκαίους νόμους ὑπαινίττεται, τοὺς ἐπὶ πρεσβύταις καὶ νέοις ἀναγραφέντας, τοὺς ἐπ’ ἄρχουσι καὶ ὑπηκόοις, τοὺς ἐπ’ εὐεργέταις καὶ εὖ πεπονθόσι, τοὺς ἐπὶ δούλοις καὶ δεσπότις.", "st": "165"}, {"sp": "N", "t": "γονεῖς μὲν γὰρ ἐν τῇ κρείττονι τῶν εἰρημένων εἰσὶ τάξει, ἐν ᾗ πρεσβύτεροι, ἡγεμόνες, εὐεργέται, δεσπόται, παῖδες δὲ ἐν τῇ καταδεεστέρᾳ, ἐν ᾗ νεώτεροι, ὑπήκοοι, εὖ πεπονθότες, δοῦλοι.", "st": "166"}, {"sp": "N", "t": "πολλὰ δὲ καὶ ἄλλα προστέτακται, νέοις μὲν εἰς ἀποδοχὴν γήρως, πρεσβύταις δ’ εἰς ἐπιμέλειαν νεότητος, καὶ ὑπηκόοις μὲν εἰς πειθαρχίαν ἡγεμόνων, ἡγεμόσι δ’ εἰς ὠφέλειαν τῶν ἀρχομένων, καὶ εὖ μὲν πεπονθόσιν εἰς χαρίτων ἀμοιβάς, ἄρξασι δὲ δωρεῶν εἰς τὸ μὴ ζητεῖν καθάπερ ἐν δανείοις ἀπόδοσιν, καὶ θεράπουσι μὲν εἰς ὑπηρεσίαν φιλοδέσποτον, δεσπόταις δ’ εἰς ἠπιότητα καὶ πρᾳότητα, δι’ ὧν ἐξισοῦται τὸ ἄνισον.", "st": "167"}, {"sp": "N", "t": "ἇι ἡ μὲν προτέρα πεντὰς ἐν τούτοις περατοῦται κεφαλαιώδη τύπον περιέχουσα, τῶν δ’ ἐν εἴδει νόμων οὐκ ὀλίγος ἀριθμός. τῆς δ’ ἑτέρας πρῶτόν ἐστι κεφάλαιον τὸ κατὰ μοιχῶν, ᾧ ὑποτέτακται πλεῖστά διατάγματα, τὸ κατὰ φθορέων, τὸ κατὰ παιδεραστῶν, τὸ κατὰ τῶν λαγνίστερον βιούντων ὁμιλίαις τε καὶ μίξεσιν ἐκνόμοις καὶ ἀκολάστοις χρωμένων.", "st": "168"}, {"sp": "N", "t": "τὰς δὲ ἰδέας ἀναγέγραφεν οὐχ ὑπὲρ τοῦ μηνῦσαι τὸ πολύχουν καὶ πολύτροπον τῆς ἀκρασίας, ἀλλ’ ὑπὲρ τοῦ τοὺς ἀσχημόνως ζῶντας ἐμφανέστατα δυσωπεῖν ἐπαντλοῦντα τοῖς ὠσὶν αὐτῶν ἀθρόα ὀνείδη, δι’ ὧν ἐρυθριάσουσι.", "st": "169"}, {"sp": "N", "t": "δεύτερον δὲ κεφάλαιον ἡ τοῦ μὴ ἀνδροφονεῖν ἀπαγόρευσις, ὑφ’ ἥν εἰσ’· πάντες οἱ περὶ βιαίων, ὕβρεως, αἰκίας, τραυμάτων, πηρώσεως ἀναγκαῖοι νόμοι καὶ σφόδρα κοινωφελεῖς.", "st": "170"}, {"sp": "N", "t": "τρίτον δὲ τὸ περὶ τοῦ μὴ κλέπτειν, ᾧ ὑποτέτακται τὰ ἐπὶ χρεωκοπίαις ὁρισθέντα καὶ ἐξάρνοις παρακαταθηκῶν καὶ ἀκοινωνήτῳ κοινωνίᾳ καὶ ἀναισχύντοις ἁρπαγαῖς καὶ συνόλως πλεονεξίαις, ὑφ’ ὧν πείθονταί τινες φανερῶς ἢ λάθρα τἀλλότρια νοσφίζεσθαι.", "st": "171"}, {"sp": "N", "t": "τέταρτον δὲ τὸ περὶ τοῦ μὴ ψευδομαρτυρεῖν, ᾧ πολλὰ ἐμφέρεται, τὸ μὴ ἀπατᾶν, τὸ μὴ συκοφαντεῖν, τὸ μὴ τοῖς ἐξαμαρτάνουσι συμπράττειν, τὸ μὴ ποιεῖσθαι προκάλυμμα πίστιν ἀπιστίας, ἐφ’ οἷς ἅπασι νόμοι προσήκοντες ἐτέθησαν.", "st": "172"}, {"sp": "N", "t": "πέμπτον δὲ τὸ ἀνεῖργον τὴν τῶν ἀδικημάτων πηγήν, ἐπιθυμίαν, ἀφ’ ἧς ῥέουσιν αἱ παρανομώταται πράξεις, ἴδιαι καὶ κοιναί, μικραὶ καὶ μεγάλαι, ἱεραὶ κὼ βέβηλοι, περί τε σώματα καὶ ψυχὰς καὶ τὰ λεγόμενα ἐκτός· διαφεύγει γὰρ οὐδέν, ὡς καὶ πρότερον ἐλέχθη, τὴν ἐπιθυμίαν, ἀλλ’ οἷα φλὸξ ἐν ὕλη νέμεται δαπανῶσα πάντα καὶ φθείρουσα.", "st": "173"}, {"sp": "N", "t": "πολλὰ δὲ καὶ τῶν ὑποπιπτόντων αὐτῇ διατέτακται πρός τε νουθεσίας ἐπανόρθωσιν ἐνδεχομένων καὶ πρὸς κόλασιν ἀφηνιαστῶν ὅλον τὸν βίον ἐνδεδωκότων τῷ πάθει.", "st": "174"}, {"sp": "N", "t": "τοσαῦτα καὶ περὶ τῆς δευτέρας πεντάδος ἀποχρώντως λέλεκται πρὸς ἐκπλήρωσιν τῶν δέκα λογίων, ἅπερ ἱεροπρεπῶς ἔχρησεν αὐτὸς ὁ θεός. ἦν γὰρ ἁρμόττον αὐτοῦ τῇ φύσει, κεφάλαια μὲν τῶν ἐν εἴδει νόμων αὐτοπροσώπως θεσπίσαι, νόμους δὲ τοὺς ἐν τῷ μέρει διὰ τοῦ τελειοτάτου τῶν προφητῶν, ὃν ἐπικρίνας ἀριστίνδην καὶ ἀναπλήσας ἐνθέου πνεύματος ἑρμηνέα τῶν χρησμῳδουμένων εἵλετο.", "st": "175"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα λέγωμεν τὴν αἰτίαν, δι’ ἣν τοὺς δέκα λόγους ἢ νόμους ἀπεφήνατο ψιλαῖς προστάξεσι καὶ ἀπαγορεύσεσι κατὰ τῶν παραβησομένων, ὡς ἔθος νομοθέταις, μηδὲν ὁρίσας ἐπιτίμιον· θεὸς ἦν, εὐθὺς δὲ κύριος ἀγαθός, μόνων ἀγαθῶν αἴτιος, κακοῦ δ’ οὐδενός.", "st": "176"}, {"sp": "N", "t": "οἰκειότατον οὖν ὑπολαβὼν αὑτοῦ τῇ φύσει τὰ σωτήρια κελεύειν ἀμιγῆ καὶ ἀμέτοχα τιμωρίας, ἵνα μή πως φόβῳ τις ἄφρονι συμβούλῳ χρησάμενος ἄκων ἀλλ’ ἔμφρονι λογισμῷ καθ’ ἑκούσιον γνώμην αἱρῆται τὰ βέλτιστα, μετὰ κολάσεως οὐκ ἠξίωσε θεσπίζειν, οὐκ ἀσυλίαν τοῖς ἀδικοπραγοῦσι διδούς, ἀλλ’ εἰδὼς τὴν πάρεδρον αὑτῷ δίκην καὶ τῶν ἀνθρωπίνων ἔφορον πραγμάτων οὐκ ἠρεμήσουσαν ἅτε φύσει μισοπόνηρον καὶ ὥσπερ τι συγγενὲς ἔργον ἐκδεξομένην τὴν κατὰ τῶν ἁμαρτανόντων ἄμυναν.", "st": "177"}, {"sp": "N", "t": "ἐμπρεπὲς γὰρ ὑπηρέταις μὲν καὶ ὑπάρχοις θεοῦ καθάπερ τοῖς πολέμου στρατηγοῖς ἐπὶ λιποτάκταις οἳ λείπουσι τὴν τοῦ δικαίου τάξιν ἀμυντηρίοις χρῆσθαι, τῷ δὲ μεγάλῳ βασιλεῖ τὴν κοινὴν ἀσφάλειαν ἐπιγεγράφθαι τοῦ παντός, εἰρηνοφυλακοῦντι καὶ τὰ τῆς εἰρήνης ἀγαθὰ πάντα τοῖς πανταχοῦ πᾶσιν ἀεὶ πλουσίως καὶ ἀφθόνως χορηγοῦντι· τῷ γὰρ ὄντι ὁ μὲν θεὸς πρύτανις εἰρήνης, οἱ δ’ ὑποδιάκονοι πολέμων ἡγεμόνες εἰσίν.", "st": "178"}], []);})();
